# Python equality is strict in JS terms — use === / !==. The one exception is
# a comparison against a literal None, which keeps the loose == / != (see the
# "compare" arm of _gen_expr).
_JS_CMP = {"==": "===", "!=": "!=="}

#: http.<method> -> the suffix of its Workpeg.http<Name> runtime helper, for
#: the methods str.capitalize() would get wrong. Every other verb is a single
#: lowercase word, where capitalize() is already right.
_HTTP_HELPERS = {"post_file": "PostFile"}


#: What cannot be written as itself inside a JS template literal.
#:
#: A backslash, a backtick and ``${`` would end the literal or start something
#: else. A carriage return is the quiet one: the language normalises a raw CR
#: or CRLF in a template to LF, so the string came back changed. A lone
#: surrogate cannot be encoded as UTF-8 at all, and handed raw to rjsmin's C
#: extension it took the whole build down with a segmentation fault.
_TEMPLATE_UNSAFE = re.compile("[\\\\`\r\ud800-\udfff]|\\$\\{")


def _template_escape(match: "re.Match[str]") -> str:
    text = match.group(0)
    if text == "\r":
        return "\\r"
    if "\ud800" <= text <= "\udfff":
        return f"\\u{ord(text):04x}"
    return "\\" + text


def _escape_template_text(text: str) -> str:
    """*text* as it must appear between the backticks to come back exactly."""
    return _TEMPLATE_UNSAFE.sub(_template_escape, text)


def _is_object_prototype_name(key: str) -> bool:
    """Names that are members of the value rather than keys of a dict. A Python
    dict has no such member, so a literal ``d["toString"]`` must NOT read the
    inherited function: it routes through Workpeg.getItem, which does an
    own-property lookup. So ``row["call"]`` finds the column and ``fn["call"]``
    finds nothing, and the word stays free for a customer's data."""
    return key in _REFLECTION_MEMBERS


#: Expression kinds that are never a function, so a dict literal holding only these
#: and literals needs no check when the page runs. Anything else is checked, a kind
#: added later included: `Workpeg.dict` is only ever an unneeded call.
_NEVER_A_FUNCTION = frozenset((
    "biz_url", "binop", "clock", "colorscheme", "compare", "contains", "dict",
    "len", "list", "location", "mathconst", "platform", "query", "route",
    "template", "unary", "user",
))


def _could_be_a_function(value: Any) -> bool:
    if isinstance(value, dict):
        return value.get("expr") not in _NEVER_A_FUNCTION
    return isinstance(value, list)


#: Builtins whose result is already a JS boolean.
_BOOLEAN_BUILTINS = frozenset(("isarray", "any", "all"))


def _contains_await(node: Any) -> bool:
    """Whether an IR subtree contains an ``await``.

    Anything that puts such a subtree inside a plain arrow has to make that
    arrow async — otherwise the emitted `await` sits in a non-async function
    and the bundle fails to parse.
    """
    if isinstance(node, dict):
        if node.get("expr") == "await":
            return True
        return any(_contains_await(v) for v in node.values())
    if isinstance(node, (list, tuple)):
        return any(_contains_await(v) for v in node)
    return False


def _is_boolean_expr(node: Any) -> bool:
    """Whether *node* already evaluates to a real boolean.

    Python and JS agree on truthiness for everything EXCEPT an empty list or
    dict, so a condition only needs the Workpeg.truthy wrapper when it could
    produce a container. A comparison never can — and comparisons are what
    most conditions are — so this keeps `if a > 0 and b < 10` compiling to
    exactly the JS it did before.
    """
    if isinstance(node, bool):
        return True
    if not isinstance(node, dict):
        return False
    kind = node.get("expr")
    if kind in ("compare", "contains"):
        return True
    if kind == "unary":
        return node.get("op") == "!"
    if kind == "logic":
        # `a and b` yields an OPERAND, so it is boolean only when every
        # operand is.
        return all(_is_boolean_expr(v) for v in node.get("values", ()))
    if kind == "builtin":
        return node.get("fn") in _BOOLEAN_BUILTINS
    if kind == "cond":
        return (_is_boolean_expr(node.get("then"))
                and _is_boolean_expr(node.get("else")))
    return False


# Emitted prop keys for the universal interaction handlers (see the parser's
# _INTERACTION_EVENTS). Spliced into props by _with_extras and bound centrally
# by the runtime's design-system hook.
_INTERACTION_EVENT_PROPS = (
    "onDblClick", "onMouseEnter", "onMouseLeave", "onFocus", "onBlur", "onKey",
)

# GestureDetector handler props, in emission order.
_GESTURE_PROPS = (
    "onTap", "onDoubleTap", "onLongPress",
    "onSwipeLeft", "onSwipeRight", "onSwipeUp", "onSwipeDown",
)


def _is_list_literal(node: Any) -> bool:
    """True when an expression is a list literal ``[...]`` — so a surrounding
    ``+`` means list concatenation, not numeric/string addition."""
    return isinstance(node, dict) and node.get("expr") == "list"


def _is_list_valued(node: Any) -> bool:
    """True when an expression is provably a list, so a ``+`` beside it is
    list concatenation.

    A literal alone was not enough. ``[a] + [x for x in xs] + [b] + [y for y
    in ys]`` concatenates left to right, and its last ``+`` has a
    concatenation on the left and a comprehension on the right — neither a
    literal — so it compiled to JS ``+``, which joins two arrays as TEXT;
    the ``+ [...]`` after it then spread that text into single characters.
    A Dropdown fed that list rendered a button reading the raw value and a
    panel of one-letter rows, with no error anywhere. ``self.rows + [r for r
    in extra]`` failed the same way. A comprehension, ``range``/``sorted``/
    ``list`` and a concatenation are as surely lists as a literal is.

    Two operands of unknown type (``self.a + self.b``) still compile to
    ``+``: they are as likely to be strings or numbers, and guessing list
    there would break every text concatenation instead.
    """
    if _is_list_literal(node) or ASTParser._is_certainly_a_sequence(node):
        return True
    return (isinstance(node, dict) and node.get("expr") == "binop"
            and node.get("op") == "+"
            and (_is_list_valued(node.get("left"))
                 or _is_list_valued(node.get("right"))))


# Whitelisted builtins → their JS equivalents. Number/Math.trunc coerce strings
# the way Python float()/int() do; Workpeg.round is Python-faithful (half-even).
# str → String (JS coercion: a number/string stringifies as Python would; a
# bool/None render lowercase JS-style — true/null, not True/None).
_JS_CALLS = {
    "abs": "Math.abs", "min": "Math.min", "max": "Math.max",
    "float": "Number", "int": "Math.trunc", "round": "Workpeg.round",
    "pow": "Math.pow", "str": "String",
}

# stdlib math.<fn> → JS Math.* (math.log is special-cased for its optional base).
_JS_MATH = {
    "sqrt": "Math.sqrt", "floor": "Math.floor", "ceil": "Math.ceil",
    "trunc": "Math.trunc", "fabs": "Math.abs", "exp": "Math.exp",
    "log2": "Math.log2", "log10": "Math.log10",
    "sin": "Math.sin", "cos": "Math.cos", "tan": "Math.tan",
    "asin": "Math.asin", "acos": "Math.acos", "atan": "Math.atan",
    "pow": "Math.pow", "hypot": "Math.hypot", "atan2": "Math.atan2",
}
_JS_MATH_CONST = {
    "pi": "Math.PI", "e": "Math.E", "tau": "(Math.PI * 2)",
    "inf": "Infinity", "nan": "NaN",
}

