class JSGenerator:

    #: Set True while generating if the app renders any ``Icon`` — the build
    #: reads it to link the icon stylesheet only when it's needed. WHICH icons
    #: (for subsetting) and whether any is dynamic are collected by the parser
    #: (ASTParser.icon_names / .dynamic_icons), which sees component icon props.
    uses_icons = False

    #: Whether this build mounts the Workpeg chrome (a Scaffold), i.e. whether
    #: it lazily fetches scaffold.js / ai.js at runtime. Drives the CDN
    #: preconnect: an app with no Scaffold never loads either.
    uses_chrome = False

    #: Set while generating a Component with a prop called ``state``.
    _state_is_a_prop = False

    #: Set True while generating if the page names anything of WebRTC's: a
    #: fixed handle, a constructor, a member or a settable. The build reads
    #: it to ship rtc.js only to a peg that uses it.
    uses_rtc = False

    def generate(self, ir: "AppIR | RouterIR") -> str:
        self.uses_icons = False
        self.uses_chrome = False
        self.uses_rtc = False
        if isinstance(ir, RouterIR):
            return self._generate_router(ir)
        return self._generate_app(ir)

    # ------------------------------------------------------------------ router

    def _generate_router(self, ir: RouterIR) -> str:
        parts: list[str] = []
        # Components first so they're defined when the page classes reference them.
        for comp in ir.components:
            parts.append(self._gen_component_class(comp))
            parts.append("")
        # Emit each distinct class once, by name — a shell or page app may be
        # shared by several routes (e.g. one stub page behind many paths), and a
        # class must not be declared twice.
        emitted: set[str] = set()
        classes = list(ir.shells) + [r.app for r in ir.routes]
        if ir.not_found is not None:
            classes.append(ir.not_found)
        for cls in classes:
            if cls.name in emitted:
                continue
            emitted.add(cls.name)
            parts.append(self._gen_app_class(cls))
            parts.append("")
        parts.append(self._gen_router_bootstrap(ir))
        return "\n".join(parts)

    def _gen_router_bootstrap(self, ir: RouterIR) -> str:
        entries = []
        for r in ir.routes:
            shell = f", shell: {r.shell.name}" if r.shell is not None else ""
            entries.append(
                f"    {{ path: {json.dumps(r.path)}, app: {r.app.name}{shell} }}"
            )
        routes_js = "[\n" + ",\n".join(entries) + "\n  ]"
        # Pass the not-found class as the second argument when declared.
        nf_arg = f", {ir.not_found.name}" if ir.not_found is not None else ""
        lines = ['window.addEventListener("load", function() {']
        if ir.theme is not None:
            # Re-theme pegment's tokens before anything renders.
            lines.append(f"  Workpeg.applyTheme({json.dumps(ir.theme)});")
        if ir.store is not None:
            # The global store is initialised once, before any page mounts.
            lines.append(f"  Workpeg.initStore({json.dumps(ir.store)});")
        if ir.translations is not None:
            # The message catalogue + active language, before any page renders.
            lines.append(
                f"  Workpeg.initLocale({json.dumps(ir.translations)});"
            )
        lines.append(f"  Workpeg.router({routes_js}{nf_arg});")
        lines.append("});")
        return "\n".join(lines)

    # ----------------------------------------------------------------- single app

    def _generate_app(self, ir: AppIR) -> str:
        parts: list[str] = []
        for comp in ir.components:
            parts.append(self._gen_component_class(comp))
            parts.append("")
        parts.append(self._gen_app_class(ir))
        parts.append("")
        parts.append(
            self._gen_bootstrap(ir.name, ir.store, ir.theme, ir.translations)
        )
        return "\n".join(parts)

    # -------------------------------------------------------------- components

    def _gen_component_class(self, ir: "ComponentIR") -> str:
        # In a class with a prop called `state`, this.state is that prop, so a
        # `${x}` token is not a read of a field. See `_text_to_js`.
        self._state_is_a_prop = "state" in (
            [*ir.props, *ir.kwonly, ir.variadic] + [f for f, _ in ir.init])
        try:
            return self._gen_component_body(ir)
        finally:
            self._state_is_a_prop = False

    def _gen_component_body(self, ir: "ComponentIR") -> str:
        parts: list[str] = [f"class {ir.name} {{", ""]

        ctor: list[str] = ["  constructor(props) {"]
        if ir.states:
            ctor.append(self._gen_state_proxy(ir.states, ir.name, 4))
        ctor.append("    this._applyProps(props);")
        ctor.append("  }")
        parts.append("\n".join(ctor))
        parts.append("")

        # _applyProps runs on first construct and again on every re-render the
        # parent triggers (so derived fields recompute when props change, while
        # this.state is untouched). Bind each param as a local, auto-apply the
        # ones the __init__ body doesn't set itself, then run the body.
        assigned = {field for field, _ in ir.init}
        params = (
            list(ir.props) + list(ir.kwonly)
            + ([ir.variadic] if ir.variadic else [])
        )
        apply: list[str] = ["  _applyProps(props) {"]
        for prop in params:
            apply.append(f"    const {prop} = props.{prop};")
        for prop in params:
            if prop not in assigned:
                apply.append(f"    this.{prop} = {prop};")
        for field, value in ir.init:
            apply.append(f"    this.{field} = {self._gen_expr(value)};")
        apply.append("  }")
        parts.append("\n".join(apply))
        parts.append("")

        # A stateful component re-renders the root when its own state changes;
        # the runtime reuses this instance, so its state survives the re-render.
        if ir.states:
            parts.append("  render() {\n    Workpeg.render();\n  }")
            parts.append("")

        for method in ir.methods:
            parts.append(self._gen_method(method))
            parts.append("")

        parts.append(self._gen_build(ir.tree))
        parts.append("")
        parts.append("}")
        return "\n".join(parts)

    def _gen_component_node(self, widget: WidgetIR) -> str:
        name = widget.props["component"]
        args = widget.props["args"]
        key = widget.props["key"]
        entries = []
        for k, v in args.items():
            if isinstance(v, WidgetIR):
                # A widget child: render it as a node, bound to the parent that
                # wrote it, so its handlers resolve to the parent (not the
                # component). The runtime renders it inside the component's slot.
                entries.append(f"{k}: Workpeg.boundChild(this, {self._gen_widget(v)})")
            elif isinstance(v, list):
                # A *children slot — an array of widgets, each bound to the
                # parent (rendered via *self.<slot> in the component's build).
                items = ", ".join(
                    f"Workpeg.boundChild(this, {self._gen_widget(w)})"
                    if isinstance(w, WidgetIR) else self._gen_expr(w)
                    for w in v
                )
                entries.append(f"{k}: [{items}]")
            else:
                entries.append(f"{k}: {self._gen_expr(v)}")
        props_js = "{ " + ", ".join(entries) + " }" if entries else "{}"
        # With a user `key=`, the cache key combines the lexical site with the
        # per-iteration value, so each loop item gets its own instance (and its
        # own state) instead of all sharing the one site.
        if "item_key" in widget.props:
            item = self._gen_expr(widget.props["item_key"])
            key_js = f"{json.dumps(key + '-')} + ({item})"
        else:
            key_js = json.dumps(key)
        return f"Workpeg.component({name}, {props_js}, {key_js})"

    def _gen_app_class(self, ir: AppIR) -> str:
        parts: list[str] = []
        parts.append(f"class {ir.name} {{")
        parts.append("")
        parts.append(self._gen_constructor(ir))
        parts.append("")

        for method in ir.methods:
            parts.append(self._gen_method(method))
            parts.append("")

        parts.append(self._gen_build(ir.tree))
        parts.append("")
        parts.append(self._gen_render())
        parts.append("")
        parts.append("}")
        return "\n".join(parts)

    def _gen_state_proxy(
        self, states: list, cls_name: str, indent: int
    ) -> str:
        """Emit ``this.state = new Proxy({…}, Workpeg.stateHandler(this[, map]))``.

        A `persist=True` field restores its value from localStorage on construct
        (``Workpeg.loadState``) and is registered in a persist map so the state
        handler mirrors every change back. Keyed by class + field, stable across
        reloads.
        """
        pad = " " * indent
        persist = {
            s.name: f"wp:{cls_name}:{s.name}" for s in states if s.persist
        }
        lines = [f"{pad}this.state = new Proxy({{"]
        for i, s in enumerate(states):
            comma = "," if i < len(states) - 1 else ""
            if s.persist:
                val = (
                    f"Workpeg.loadState({json.dumps(persist[s.name])}, "
                    f"{json.dumps(s.default)})"
                )
            else:
                val = json.dumps(s.default)
            lines.append(f"{pad}  {s.name}: {val}{comma}")
        # Workpeg.stateHandler re-renders on field assignment and wraps array
        # fields so in-place mutations (push/pop/splice/...) are reactive; the
        # optional persist map mirrors those fields to localStorage.
        if persist:
            lines.append(
                f"{pad}}}, Workpeg.stateHandler(this, {json.dumps(persist)}));"
            )
        else:
            lines.append(f"{pad}}}, Workpeg.stateHandler(this));")
        return "\n".join(lines)

    def _gen_constructor(self, ir: AppIR) -> str:
        lines: list[str] = []
        lines.append("  constructor() {")
        lines.append(self._gen_state_proxy(ir.states, ir.name, 4))
        if ir.title is not None:
            # The page's document <title>; the runtime assigns it to
            # document.title when this page mounts (Workpeg._applyTitle).
            lines.append(f"    this._pageTitle = {json.dumps(ir.title)};")
        lines.append("  }")
        return "\n".join(lines)

    def _gen_method(self, method: MethodIR) -> str:
        lines: list[str] = []
        params = ", ".join(method.params)
        prefix = "async " if method.is_async else ""
        lines.append(f"  {prefix}{method.name}({params}) {{")
        # Hoisted locals (assigned inside an if/for block) are declared up front
        # so their value survives the block, matching Python function scoping.
        if method.locals:
            lines.append(f"    let {', '.join(method.locals)};")
        for stmt in method.statements:
            lines.append(self._gen_statement(stmt, indent=4))
        # CPython hands back None from a function that ends without a
        # `return`; JS hands back undefined, which `==` against a local
        # holding None, `in [None]`, str(), `visible=` and JSON all tell from
        # null. So a method that may reach its end ends as `return None`
        # does — every one, not only those returning a value elsewhere, since
        # 12 minified bytes each (+1% on the playground's app.js, +0.4%
        # gzipped) buy a rule with no exception. Only a last top-level
        # `return` is recognised: an if/else returning in both arms gets a
        # dead `return null;`, never a wrong answer.
        if not method.statements or method.statements[-1].type != "return":
            lines.append("    return null;")
        lines.append("  }")
        return "\n".join(lines)

    def _gen_statement(self, stmt: StatementIR, indent: int = 4) -> str:
        pad = " " * indent

        if stmt.type == "log":
            args = ", ".join(self._gen_expr(a) for a in stmt.data["args"])
            return f"{pad}console.log({args});"

        if stmt.type == "local":
            name = stmt.data["name"]
            op = stmt.data["operator"]
            value = self._gen_expr(stmt.data["value"])
            if stmt.data.get("declare"):
                return f"{pad}let {name} = {value};"
            if op == "=":
                return f"{pad}{name} = {value};"
            return f"{pad}{name} {op}= {value};"

        if stmt.type == "expr_stmt":
            return f"{pad}{self._gen_expr(stmt.data['value'])};"

        if stmt.type == "return":
            # `return None` and a bare `return` parse alike, and both hand the
            # caller None. A JS `return;` hands it undefined, which a strict
            # `=== null` tells apart from null — so `self.parse(s) == None`
            # was True in CPython and false in the page. `null` is None (and
            # the end of a method returns it too: see _gen_method).
            value = stmt.data.get("value")
            return f"{pad}return {self._gen_expr(value)};"

        if stmt.type == "subscript_set":
            return pad + self._gen_subscript_set(stmt.data)

        if stmt.type == "subscript_del":
            return pad + self._gen_subscript_del(stmt.data)

        if stmt.type == "for_loop":
            return self._gen_for_loop(stmt.data, indent)

        if stmt.type == "if":
            return self._gen_if(stmt.data, indent)

        if stmt.type == "try":
            return self._gen_try(stmt.data, indent)

        if stmt.type == "timer":
            fn = "setInterval" if stmt.data["kind"] == "interval" else "setTimeout"
            handler = stmt.data["handler"]
            ms = self._gen_expr(stmt.data["ms"])
            # Bound to `this` so the callback re-renders the right instance; the
            # runtime registers it against the app for cleanup on navigation.
            return f"{pad}Workpeg.{fn}(this, () => this.{handler}(), {ms});"

        if stmt.type == "set_theme":
            # Runtime re-theme: swap the active Pegment tokens on :root.
            return f"{pad}Workpeg.applyTheme({json.dumps(stmt.data['tokens'])});"

        if stmt.type == "set_color_scheme":
            # Switch light/dark via Pegment's .dark / .light classes on <html>.
            return f"{pad}Workpeg.setColorScheme({json.dumps(stmt.data['mode'])});"

        if stmt.type == "toggle_sidebar":
            # Flip the Scaffold's collapse class on <html> — a side-effect, not a
            # re-render, so the CSS-variable width/label transitions can fire.
            return f"{pad}Workpeg.toggleSidebar();"

        if stmt.type == "toggle_incognito":
            # Flip incognito-chat mode's class on <html> — the AI surface keys
            # its whole incognito UX (and chat creation) off it.
            return f"{pad}Workpeg.toggleIncognito();"

        if stmt.type == "toggle_ai_history":
            # Reach into the AI surface to slide its history drawer in/out —
            # the top-bar History button on an open conversation.
            return f"{pad}Workpeg.toggleAIHistory();"

        if stmt.type == "set_title":
            # Imperative document.title — inert text (may interpolate state).
            # Emitted like a Text() value: a structured f-string is an expression
            # node; a plain string or compact template goes through _text_to_js.
            value = stmt.data["value"]
            js_value = (
                self._gen_expr(value) if isinstance(value, dict)
                else self._text_to_js(value)
            )
            return f"{pad}Workpeg.setTitle({js_value});"

        if stmt.type == "toast":
            # A transient notification — the message may interpolate state (an
            # f-string); kind is a static severity for the colour.
            msg = stmt.data["message"]
            msg_js = (self._gen_expr(msg) if isinstance(msg, dict)
                      else self._text_to_js(msg))
            return f"{pad}Workpeg.toast({msg_js}, {json.dumps(stmt.data['kind'])});"

        if stmt.type == "copy":
            # Copy inert text to the clipboard (the value may interpolate state).
            value = stmt.data["value"]
            val_js = (self._gen_expr(value) if isinstance(value, dict)
                      else self._text_to_js(value))
            return f"{pad}Workpeg.copy({val_js});"

        if stmt.type == "navigate":
            # Programmatic SPA navigation (the url may interpolate state/route).
            value = stmt.data["value"]
            val_js = (self._gen_expr(value) if isinstance(value, dict)
                      else self._text_to_js(value))
            return f"{pad}Workpeg.navigate({val_js});"

        if stmt.type == "reload":
            # Full-page reload/navigation (the optional url may interpolate).
            value = stmt.data.get("value")
            if value is None:
                return f"{pad}Workpeg.reload();"
            val_js = (self._gen_expr(value) if isinstance(value, dict)
                      else self._text_to_js(value))
            return f"{pad}Workpeg.reload({val_js});"

        if stmt.type == "cookie_set":
            # Write a *.workpeg-shared cookie (name/value may interpolate state).
            name, value = stmt.data["name"], stmt.data["value"]
            name_js = (self._gen_expr(name) if isinstance(name, dict)
                       else self._text_to_js(name))
            val_js = (self._gen_expr(value) if isinstance(value, dict)
                      else self._text_to_js(value))
            return f"{pad}Workpeg.setCookie({name_js}, {val_js});"

        if stmt.type in ("geo_current", "geo_watch"):
            # Browser geolocation; handlers bound to `this` so the page's methods
            # receive the coords object / error message.
            d = stmt.data
            res = f'(r) => this.{d["on_result"]}(r)'
            err = f'(e) => this.{d["on_error"]}(e)' if d["on_error"] else "null"
            fn = "geoCurrent" if stmt.type == "geo_current" else "geoWatch"
            return f"{pad}Workpeg.{fn}(this, {res}, {err});"

        if stmt.type == "geo_clear":
            return f"{pad}Workpeg.geoClear(this);"

        if stmt.type == "mic_listen":
            d = stmt.data
            lvl = f'(l) => this.{d["on_level"]}(l)' if d["on_level"] else "null"
            err = f'(e) => this.{d["on_error"]}(e)' if d["on_error"] else "null"
            return f"{pad}Workpeg.micListen(this, {lvl}, {err});"

        if stmt.type == "mic_stop":
            return f"{pad}Workpeg.micStop(this);"

        if stmt.type == "socket_connect":
            # The managed WebSocket for this page; handlers are bound to `this`
            # so the page's methods receive the message / open / close events.
            d = stmt.data
            url = d["url"]
            url_js = (self._gen_expr(url) if isinstance(url, dict)
                      else self._text_to_js(url))
            msg = f'(d) => this.{d["on_message"]}(d)'
            opn = f'() => this.{d["on_open"]}()' if d["on_open"] else "null"
            cls = f'() => this.{d["on_close"]}()' if d["on_close"] else "null"
            return (
                f"{pad}Workpeg.socketConnect(this, {url_js}, {msg}, "
                f"{opn}, {cls});"
            )

        if stmt.type == "socket_send":
            return (
                f"{pad}Workpeg.socketSend(this, "
                f"{self._gen_expr(stmt.data['value'])});"
            )

        if stmt.type == "socket_close":
            return f"{pad}Workpeg.socketClose(this);"

        if stmt.type == "events_connect":
            # The managed Server-Sent Events stream for this page; handlers are
            # bound to `this` so the page's methods receive each event's data.
            d = stmt.data
            url = d["url"]
            url_js = (self._gen_expr(url) if isinstance(url, dict)
                      else self._text_to_js(url))
            msg = (f'(d) => this.{d["on_message"]}(d)'
                   if d["on_message"] else "null")
            opn = f'() => this.{d["on_open"]}()' if d["on_open"] else "null"
            err = f'() => this.{d["on_error"]}()' if d["on_error"] else "null"
            named = d.get("named") or []
            if named:
                pairs = ", ".join(
                    f"[{json.dumps(name)}, (d) => this.{handler}(d)]"
                    for name, handler in named
                )
                named_js = f"[{pairs}]"
            else:
                named_js = "null"
            return (
                f"{pad}Workpeg.eventsConnect(this, {url_js}, {msg}, "
                f"{opn}, {err}, {named_js});"
            )

        if stmt.type == "events_close":
            return f"{pad}Workpeg.eventsClose(this);"

        if stmt.type == "scheme_listener":
            # Call the handler whenever the OS colour-scheme preference changes;
            # registered against the app so it's cleared on navigation.
            handler = stmt.data["handler"]
            return f"{pad}Workpeg.onColorScheme(this, () => this.{handler}());"

        if stmt.type == "table_listener":
            # Hear a table or row change; the runtime holds the token and the
            # socket. The handler is a method of this class (the parser
            # checked), and a dynamic table is made a string, so a value that
            # is None at runtime is refused there instead of widening one
            # table into all of them.
            handler = stmt.data["handler"]
            table = stmt.data["table"]
            if table is None:
                table_js = "null"
            elif stmt.data.get("dynamic"):
                table_js = f'("" + ({self._gen_expr(table)}))'
            else:
                table_js = json.dumps(table)
            return (f"{pad}Workpeg.onTableChange(this, "
                    f"(e) => this.{handler}(e), {table_js});")

        if stmt.type == "shortcut":
            # A global keyboard shortcut, registered against the app so it's
            # cleared on navigation. modifier=True → Cmd/Ctrl + key; False → a
            # plain key (ignored while typing in a form field).
            handler = stmt.data["handler"]
            key = json.dumps(stmt.data["key"])
            mod = "true" if stmt.data.get("modifier", True) else "false"
            return (
                f"{pad}Workpeg.onShortcut(this, {key}, "
                f"() => this.{handler}(), {mod});"
            )

        if stmt.type not in ("state_update", "store_update"):
            raise ValueError(f"Unknown statement type: {stmt.type}")

        field = stmt.data["field"]
        op = stmt.data["operator"]
        value = self._gen_expr(stmt.data["value"])
        # Same shape for per-app state and the global store; only the target
        # differs (this.state vs the global Workpeg.store proxy).
        target = "this.state" if stmt.type == "state_update" else "Workpeg.store"
        if op == "=":
            return f"{pad}{target}.{field} = {value};"
        return f"{pad}{target}.{field} {op}= {value};"

    def _gen_test(self, node: Any) -> str:
        """Render *node* where only its truth matters (an ``if``, a ternary
        test, a ``not`` operand, a filter predicate).

        Wrapped in ``Workpeg.truthy`` unless the expression is already a
        boolean, so ordinary comparisons keep their previous output.
        """
        js = self._gen_expr(node)
        if _is_boolean_expr(node):
            return js
        return f"Workpeg.truthy({js})"

    def _gen_logic(self, value: dict) -> str:
        """Render ``and`` / ``or``.

        Python yields an OPERAND, not a bool, and chooses it by Python
        truthiness — so ``[] or default`` is ``default`` while JS's ``[] ||
        default`` is ``[]``. When every operand is already boolean the plain
        ``&&`` / ``||`` is exact and is what we emit; otherwise each step
        becomes a conditional over a bound temp, which keeps the operand
        result AND short-circuits (the right side sits inside a branch).
        """
        values = value["values"]
        if all(_is_boolean_expr(v) for v in values):
            joiner = " && " if value["op"] == "and" else " || "
            return "(" + joiner.join(self._gen_expr(v) for v in values) + ")"

        is_and = value["op"] == "and"
        # Fold from the right so `a and b and c` still short-circuits left to
        # right: each step wraps everything after it.
        js = self._gen_expr(values[-1])
        for i in range(len(values) - 2, -1, -1):
            # `$t` holds the evaluated left operand. `and` yields the rest
            # when $t is truthy (else $t itself); `or` is the mirror. Either
            # way the OPERAND comes back, not a bool, and the untaken side is
            # never evaluated. The name uses `$`, which a Python identifier
            # cannot contain, so it can never shadow an author's local.
            then, otherwise = (js, "$t") if is_and else ("$t", js)
            left = self._gen_expr(values[i])
            # An arrow is a function boundary — the same hazard _gen_for_loop
            # documents. An `await` in the DEFERRED side (everything to the
            # right, which is what the arrow body holds) would land in a
            # non-async function: a SyntaxError that kills the whole bundle
            # from a build that reported success. Python only allows await
            # inside an async def, so awaiting an async arrow is always legal
            # here. Gated, so the common case allocates no promise.
            if any(_contains_await(v) for v in values[i + 1:]):
                js = (f"await (async ($t) => Workpeg.truthy($t) "
                      f"? {then} : {otherwise})({left})")
            else:
                js = (f"(($t) => Workpeg.truthy($t) ? {then} : {otherwise})"
                      f"({left})")
        return js

    def _gen_receiver(self, node: Any) -> str:
        """What a member is read off, in parentheses where JavaScript would
        otherwise read it differently from the Python. `5.real` is a malformed
        number, and a whole bundle is one script. `await x.y` reads y off the
        Promise, because a member binds tighter than `await`."""
        js = self._gen_expr(node)
        if ((isinstance(node, (int, float)) and not isinstance(node, bool))
                or (isinstance(node, dict) and node.get("expr") == "await")):
            return f"({js})"
        return js

    def _gen_subscript_set(self, data: dict) -> str:
        target = self._gen_expr(data["target"])
        value = self._gen_expr(data["value"])
        if data["kind"] == "index":
            # No literal-key fast path on a MUTATION, so the invariant is
            # simply stated: no key ever reaches a bare obj[key] on a write.
            # It also fixes xs[-1] = v, which used to create a string property
            # "-1" while the matching read used .at(-1) — the two disagreed.
            return (f"Workpeg.setItem({target}, "
                    f"{self._gen_expr(data['index'])}, {value});")
        lo = self._gen_slice_bound(data.get("lower"))
        up = self._gen_slice_bound(data.get("upper"))
        return f"Workpeg.spliceAssign({target}, {lo}, {up}, {value});"

    def _gen_subscript_del(self, data: dict) -> str:
        target = self._gen_expr(data["target"])
        if data["kind"] == "index":
            # Not .splice: objects have none, so `del d[k]` threw.
            return f"Workpeg.delItem({target}, {self._gen_expr(data['index'])});"
        lo = self._gen_slice_bound(data.get("lower"))
        up = self._gen_slice_bound(data.get("upper"))
        return f"Workpeg.delSlice({target}, {lo}, {up});"

    def _gen_for_loop(self, data: dict, indent: int) -> str:
        """A Python ``for`` becomes a JS ``for…of``.

        Not ``.forEach(cb)``: the callback is a function boundary, so an
        ``await`` in the body lands in a non-async arrow and the whole
        bundle dies with a SyntaxError at load — a build that "succeeded".
        ``for…of`` keeps the body in the enclosing function, so ``await``
        (and ``return``) mean what they say.

        ``for i, x in enumerate(it)`` parses to params in JS callback order
        (value, index), which ``.entries()`` yields reversed — hence the
        flipped destructuring. A tuple target (``for k, v in d.items()``)
        arrives as ONE param already carrying its destructuring pattern, so it
        needs no special case here and cannot be confused with enumerate.
        """
        pad = " " * indent
        iterable = self._gen_expr(data["iter"])
        params = data["params"]
        body_lines = [
            self._gen_statement(s, indent + 2) for s in data["body"]
        ]
        body = "\n".join(body_lines)
        # `let`, not `const`: Python lets you reassign the loop variable in the
        # body (`for x in xs: x = x + 1`), which `const` turns into a runtime
        # TypeError. `let` still binds per iteration, so a closure created in
        # the body captures that iteration's value either way.
        if len(params) == 2:
            value, index = params
            head = f"for (let [{index}, {value}] of {iterable}.entries())"
        else:
            head = f"for (let {params[0]} of {iterable})"
        return (
            f"{pad}{head} {{\n"
            f"{body}\n"
            f"{pad}}}"
        )

    def _gen_if(self, data: dict, indent: int) -> str:
        pad = " " * indent
        test = self._gen_test(data["test"])
        out = f"{pad}if ({test}) {self._gen_block(data['body'], indent)}"

        orelse = data["orelse"]
        if not orelse:
            return out

        # elif: orelse is exactly one `if` -> render `else if`, not `else { if }`.
        if len(orelse) == 1 and orelse[0].type == "if":
            return out + " else " + self._gen_statement(orelse[0], indent).lstrip()

        return out + " else " + self._gen_block(orelse, indent)

    def _gen_try(self, data: dict, indent: int) -> str:
        pad = " " * indent
        out = f"{pad}try {self._gen_block(data['body'], indent)}"
        if "handler" in data:
            # ES2019 allows an unnamed catch, but bind a placeholder for
            # broad runtime support when there's no `as e`.
            name = data.get("name") or "_e"
            out += f" catch ({name}) {self._gen_block(data['handler'], indent)}"
        if "finalbody" in data:
            out += f" finally {self._gen_block(data['finalbody'], indent)}"
        return out

    def _gen_block(self, statements: list, indent: int) -> str:
        """Render statements as a brace-wrapped block (``{}`` when empty)."""
        if not statements:
            return "{}"
        pad = " " * indent
        body = "\n".join(
            self._gen_statement(s, indent + 2) for s in statements
        )
        return f"{{\n{body}\n{pad}}}"

    def _gen_rtc_fixed(self, value: dict) -> str:
        """``media_devices``: the entry rtc.js installs for a fixed handle.
        Written as code, ``Workpeg.rtc.devices``, so the node is not trusted
        to carry it: only an entry the table gives a fixed handle is
        written."""
        entry = value.get("entry")
        if entry not in {f.entry for f in rtc_tables.tables().fixed.values()}:
            raise ValueError(
                f"not a fixed WebRTC handle rtc.js's table names: {entry!r}")
        self.uses_rtc = True
        return f"Workpeg.rtc.{entry}"

    # The three WebRTC entry points. The IR names each member, settable,
    # kind and keyword by the Python name the source wrote, and is not
    # trusted to: each is looked up in rtc.js's table again here, a name the
    # table lacks raises, and what is written is json.dumps of the table's
    # own string. The owner is always the literal `this` of the method that
    # runs (contract rule 1). Arguments are a list literal and keywords an
    # object literal with computed keys, [] and {} when empty.

    def _rtc_fixed_kind(self, target: Any) -> "str | None":
        """The kind of the fixed handle `target` is, or None for any other
        receiver."""
        if not (isinstance(target, dict) and target.get("expr") == "rtc_fixed"):
            return None
        for fixed in rtc_tables.tables().fixed.values():
            if fixed.entry == target.get("entry"):
                return fixed.kind
        raise ValueError(
            f"not a fixed WebRTC handle rtc.js's table names: {target!r}")

    def _gen_rtc_list(self, args: list) -> str:
        return "[" + ", ".join(self._gen_expr(a) for a in args) + "]"

    def _gen_rtc_make(self, value: dict) -> str:
        tables = rtc_tables.tables()
        kind = value.get("kind")
        construct = tables.constructed.get(kind) if isinstance(kind, str) else None
        if construct is None:
            raise ValueError(f"not a WebRTC kind rtc.js's table makes: {kind!r}")
        entries = []
        for name, arg in value["keywords"]:
            key = next((k for k in construct.row["keywords"] if k == name), None)
            if not isinstance(name, str) or key is None:
                raise ValueError(
                    f"not a keyword of the WebRTC kind {construct.kind} in "
                    f"rtc.js's table: {name!r}")
            entries.append(f"[{json.dumps(key)}]: {self._gen_expr(arg)}")
        self.uses_rtc = True
        return (f"Workpeg.rtc.make(this, {json.dumps(construct.kind)}, "
                f"{self._gen_rtc_list(value['args'])}, "
                f"{{{', '.join(entries)}}})")

    def _gen_rtc_call(self, value: dict) -> str:
        tables = rtc_tables.tables()
        member = value.get("member")
        kind = self._rtc_fixed_kind(value["target"])
        rows = None
        if isinstance(member, str):
            if kind is not None:
                row = tables.kind_members[kind].get(member)
                rows = (row,) if row is not None else None
            else:
                rows = tables.members.get(member)
        if not rows:
            raise ValueError(
                f"not a WebRTC member rtc.js's table names: {member!r}")
        self.uses_rtc = True
        return (f"Workpeg.rtc.call(this, {self._gen_expr(value['target'])}, "
                f"{json.dumps(rows[0].browser)}, "
                f"{self._gen_rtc_list(value['args'])})")

    def _gen_rtc_set(self, value: dict) -> str:
        tables = rtc_tables.tables()
        name = value.get("name")
        rows = tables.settables.get(name, ()) if isinstance(name, str) else ()
        kind = self._rtc_fixed_kind(value["target"])
        if kind is not None:
            rows = tuple(r for r in rows if r.kind == kind)
        if not rows:
            raise ValueError(
                f"not a WebRTC property rtc.js's table lets a page set: "
                f"{name!r}")
        self.uses_rtc = True
        return (f"Workpeg.rtc.set({self._gen_expr(value['target'])}, "
                f"{json.dumps(rows[0].browser)}, "
                f"{self._gen_expr(value['value'])})")

    def _gen_rtc_listen(self, value: dict) -> str:
        """``Workpeg.rtc.on(this, h, "<event>", "<method>")``, or ``off``.
        The entry is one of the two the table's listeners name, the event
        is the table's own string, looked up again (on a fixed handle, in
        its kind's events), and the handler is written only if it is a name
        rtc.js's belt would call (C15)."""
        tables = rtc_tables.tables()
        op = value.get("op")
        if not isinstance(op, str) or op not in set(rtc_tables.LISTENERS.values()):
            raise ValueError(f"not a WebRTC listener entry: {op!r}")
        kind = self._rtc_fixed_kind(value["target"])
        events = tables.events[kind] if kind is not None else tables.all_events
        name = value.get("event")
        event = next((e for e in sorted(events) if e == name), None)
        if not isinstance(name, str) or event is None:
            raise ValueError(
                f"not an event rtc.js's table names here: {name!r}")
        handler = value.get("handler")
        if not rtc_checks.handler_name_ok(handler):
            raise ValueError(
                f"not a name rtc.js calls as a handler: {handler!r}")
        self.uses_rtc = True
        return (f"Workpeg.rtc.{op}(this, {self._gen_expr(value['target'])}, "
                f"{json.dumps(event)}, {json.dumps(handler)})")

    def _gen_expr(self, value: Any) -> str:
        """Render a statement value as a JS expression.

        Plain constants come straight from json.dumps. Composite expressions
        arrive as dicts tagged with an "expr" key (see ASTParser._parse_expr)
        and are walked recursively. Every composite node is parenthesised, so
        no operator-precedence table is needed.
        """
        if not isinstance(value, dict):
            return json.dumps(value)

        kind = value["expr"]

        if kind == "state":
            return f"this.state.{value['field']}"

        if kind == "storeref":
            return f"Workpeg.store.{value['field']}"

        if kind == "prop":
            # A component prop, set on the instance by its constructor.
            return f"this.{value['name']}"

        if kind == "callprop":
            # A prop handed to a calendar keyword that takes a function. The
            # runtime reads a string there as a method name on the owner,
            # which a prop's value never is: only data puts a string in a
            # prop, so it goes on as `false`, which the runtime refuses with
            # its warning (as any other value that is no function), rather
            # than calling the Component's own method of that name.
            name = value["name"]
            return (f'(typeof this.{name} == "string" ? false : '
                    f'this.{name})')

        if kind == "methodref":
            # self.method passed as a callback prop — bound to this instance.
            return f"this.{value['name']}.bind(this)"

        if kind == "var":
            # A local variable — currently only ListView.builder lambda
            # params, which the arrow function brings into JS scope.
            return value["name"]

        if kind == "attr":
            # Attribute access on a fetched/object value: result.name
            return f"{self._gen_receiver(value['target'])}.{value['name']}"

        if kind == "problem":
            # `failure.problem` on a caught error. Defaulted to "" because the
            # value in a catch binding is whatever was thrown: the http and
            # workpeg clients stamp the property on everything they raise, but
            # a browser TypeError or a thrown string has no property to read,
            # and `undefined == "some-slug"` is a comparison that silently
            # never matches. The receiver is the catch binding — a bare name —
            # so evaluating it twice costs nothing and has no side effects.
            name = value["name"]
            return f'(({name} && {name}.problem) || "")'

        if kind == "unary":
            if value["op"] == "!":
                # `not []` is True in Python; `![]` is false in JS.
                return f"(!{self._gen_test(value['operand'])})"
            return f"({value['op']}{self._gen_expr(value['operand'])})"

        if kind == "binop":
            left = self._gen_expr(value["left"])
            right = self._gen_expr(value["right"])
            op = value["op"]
            if op == "+" and (_is_list_valued(value["left"])
                              or _is_list_valued(value["right"])):
                # Python list concatenation. JS `+` on arrays stringifies them
                # ([1,2]+[3] === "1,23"), so spread into a new array instead.
                return f"[...{left}, ...{right}]"
            if op == "//":
                # Python floor division rounds toward -inf, unlike JS |0.
                return f"Math.floor({left} / {right})"
            if op == "**":
                return f"Math.pow({left}, {right})"
            if op == "%":
                # Python modulo takes the divisor's sign; JS takes the
                # dividend's. Emulate floor-mod so negatives match Python.
                return f"(({left} % {right} + {right}) % {right})"
            return f"({left} {op} {right})"

        if kind == "compare":
            # Against a literal None the LOOSE form stays: `x == null` is true
            # for null and undefined and nothing else (not 0, "" or false),
            # which is Python's `x == None` once a page's two "nothing"
            # values are one. Undefined still reaches here from a method that
            # falls off its end and from a missing dict key.
            op = value["op"]
            against_none = value["left"] is None or value["right"] is None
            if not (against_none and op in _JS_CMP):
                op = _JS_CMP.get(op, op)
            left = self._gen_expr(value["left"])
            right = self._gen_expr(value["right"])
            return f"({left} {op} {right})"

        if kind == "logic":
            return self._gen_logic(value)

        if kind == "cond":
            test = self._gen_test(value["test"])
            then = self._gen_expr(value["then"])
            orelse = self._gen_expr(value["else"])
            return f"({test} ? {then} : {orelse})"

        if kind == "call":
            args = ", ".join(self._gen_expr(a) for a in value["args"])
            return f"{_JS_CALLS[value['fn']]}({args})"

        if kind == "mathcall":
            fn = value["fn"]
            args = [self._gen_expr(a) for a in value["args"]]
            if fn == "log":
                # math.log(x) → ln; math.log(x, base) → log_base(x).
                if len(args) == 2:
                    return f"(Math.log({args[0]}) / Math.log({args[1]}))"
                return f"Math.log({args[0]})"
            return f"{_JS_MATH[fn]}({', '.join(args)})"

        if kind == "mathconst":
            return _JS_MATH_CONST[value["name"]]

        if kind == "jsoncall":
            arg = self._gen_expr(value["args"][0])
            js_fn = "JSON.parse" if value["fn"] == "loads" else "JSON.stringify"
            return f"{js_fn}({arg})"

        if kind == "binarycall":
            args = ", ".join(self._gen_expr(a) for a in value["args"])
            return f"Workpeg.binaryRead({args})"

        if kind == "codeccall":
            args = ", ".join(self._gen_expr(a) for a in value["args"])
            helper = "Workpeg.codec" + value["fn"].capitalize()
            return f"{helper}({args})"

        if kind == "template":
            if "parts" in value:
                return self._gen_template_parts(value["parts"])
            # Compact form — same ${...} expansion as Text() values.
            return self._text_to_js(value["value"])

        if kind == "location":
            return f"window.location.{value['prop']}"

        if kind == "rtc_fixed":
            return self._gen_rtc_fixed(value)

        if kind == "rtcmake":
            return self._gen_rtc_make(value)

        if kind == "rtccall":
            return self._gen_rtc_call(value)

        if kind == "rtcset":
            return self._gen_rtc_set(value)

        if kind == "rtclisten":
            return self._gen_rtc_listen(value)

        if kind == "route":
            return f"Workpeg.routeParam({json.dumps(value['param'])})"

        if kind == "biz_url":
            return f"Workpeg.bizUrl({self._gen_expr(value['arg'])})"

        if kind == "query":
            return f"Workpeg.queryParam({json.dumps(value['param'])})"

        if kind == "user":
            return f"Workpeg.userField({json.dumps(value['field'])})"

        if kind == "colorscheme":
            return "Workpeg.colorScheme()"

        if kind == "platform":
            return "Workpeg.platform()"

        if kind == "clock":
            return f"Workpeg.clock({json.dumps(value['prop'])})"

        if kind == "clockcall":
            args = [self._gen_expr(a) for a in value["args"]]
            if value["fn"] == "now":
                return "Workpeg.clockNow()"
            # format(ts[, style]) — runtime defaults the style when omitted.
            return f"Workpeg.clockFormat({', '.join(args)})"

        if kind == "datescall":
            # Missing optional arguments arrive as undefined, which the
            # runtime reads as None, its default for every one of them.
            args = ", ".join(self._gen_expr(a) for a in value["args"])
            return f"Workpeg.dates.{value['fn']}({args})"

        if kind == "fullscreencall":
            return "Workpeg.fullscreen" + value["fn"].capitalize() + "()"

        if kind == "list":
            parts = []
            for item in value["items"]:
                if isinstance(item, dict) and "spread" in item:
                    parts.append("..." + self._gen_expr(item["spread"]))
                else:
                    parts.append(self._gen_expr(item))
            return "[" + ", ".join(parts) + "]"

        if kind == "dict":
            if any(isinstance(k, (dict, list)) for k, _ in value["pairs"]):
                # Workpeg.dictOf checks a key only known when the page runs,
                # which this literal could not do.
                pairs = ", ".join(
                    f"[{self._gen_expr(k)}, {self._gen_expr(v)}]"
                    for k, v in value["pairs"])
                return f"Workpeg.dictOf([{pairs}])"
            entries = []
            for key, val in value["pairs"]:
                vjs = self._gen_expr(val)
                # ALWAYS the computed form, even for a string literal. In a JS
                # object literal a `"__proto__": v` key is the prototype
                # setter, not a property — quoting does not help — so
                # `{"__proto__": 1}` builds an object with ZERO own keys and a
                # replaced prototype. `{["__proto__"]: 1}` is an ordinary own
                # property, which is what the Python dict meant.
                if isinstance(key, str):
                    entries.append(f"[{json.dumps(key)}]: {vjs}")
                else:
                    entries.append(f"[{self._gen_expr(key)}]: {vjs}")
            literal = "{" + ", ".join(entries) + "}"
            if any(_could_be_a_function(v) for _, v in value["pairs"]):
                # A dict never holds a function: Workpeg.dict says why.
                return f"Workpeg.dict({literal})"
            return literal

        if kind == "index":
            idx = value["index"]
            # A string-literal key is dict access and stays direct — row["id"]
            # runs on every render and is by far the densest subscript site.
            # An Object.prototype name is the exception: direct access would
            # return the inherited member where a Python dict has none (and
            # where the dispatching path returns undefined), so route it.
            if isinstance(idx, str) and not _is_object_prototype_name(idx):
                target = self._gen_receiver(value["target"])
                return f"{target}[{json.dumps(idx)}]"
            # Anything else is genuinely ambiguous — the target may be a list,
            # a string or a dict, and only the value knows. Guessing "sequence"
            # here is what made d[k] emit .at(k) and TypeError on every dict.
            target = self._gen_expr(value["target"])
            return f"Workpeg.getItem({target}, {self._gen_expr(idx)})"

        if kind == "iter":
            return f"Workpeg.iter({self._gen_expr(value['value'])})"

        if kind == "unique":
            return f"Workpeg.unique({self._gen_expr(value['value'])})"

        if kind == "fromentries":
            # Through Object.fromEntries in the runtime, not a hand-rolled loop:
            # it creates an OWN property even for "__proto__", so a dict
            # comprehension cannot pollute a prototype the way an object
            # literal would.
            return f"Workpeg.dictOf({self._gen_expr(value['value'])})"

        if kind == "dictmethod":
            parts = [self._gen_expr(value["target"])]
            parts += [self._gen_expr(a) for a in value["args"]]
            return f"Workpeg.{value['name']}({', '.join(parts)})"

        if kind == "slice":
            target = self._gen_expr(value["target"])
            lo = self._gen_slice_bound(value.get("lower"))
            up = self._gen_slice_bound(value.get("upper"))
            st = self._gen_slice_bound(value.get("step"))
            return f"Workpeg.slice({target}, {lo}, {up}, {st})"

        if kind == "len":
            # Not .length: a dict has none, so len(d) evaluated to undefined —
            # silently, making `len(d) > 0` permanently False.
            return f"Workpeg.len({self._gen_expr(value['arg'])})"

        if kind == "contains":
            container = self._gen_expr(value["container"])
            item = self._gen_expr(value["item"])
            # Not .includes: objects have none (TypeError), and Python's
            # `k in d` tests KEYS, not values.
            expr = f"Workpeg.contains({container}, {item})"
            return f"(!{expr})" if value.get("negate") else f"({expr})"

        if kind == "lambda":
            params = ", ".join(value["params"])
            body = self._gen_expr(value["body"])
            # An arrow whose body opens with `{` has a BLOCK for a body, not
            # an object: `(x) => {["v"]: x}` is a syntax error, and
            # `(x) => {}` returns undefined. A comprehension whose element is
            # a dict literal compiles to exactly that arrow, so the whole
            # bundle failed to parse: `build_ui` refused it, or, with no node
            # to check it, shipped a page that never loaded. Wrapping makes
            # it an expression again; any other body is left alone.
            if body.lstrip().startswith("{"):
                body = f"({body})"
            return f"({params}) => {body}"

        if kind == "method":
            return self._gen_method_call(value)

        if kind == "selfcall":
            args = ", ".join(self._gen_expr(a) for a in value["args"])
            return f"this.{value['name']}({args})"

        if kind == "builtin":
            return self._gen_builtin(value)

        if kind == "first":
            # next((... ), default) — first element or the default.
            arr = self._gen_expr(value["array"])
            default = self._gen_expr(value["default"])
            return f"({arr}.at(0) ?? {default})"

        if kind == "await":
            return f"await {self._gen_expr(value['value'])}"

        if kind == "action":
            # A declarative Button(action=…) becomes the same inline arrow a
            # lambda handler would, so the runtime binds one kind of thing.
            act = value["action"]
            if act == "navigate":
                arg = value["args"][0]
                url = (self._gen_expr(arg) if isinstance(arg, dict)
                       else self._text_to_js(arg))
                return f"() => Workpeg.navigate({url})"
            field = value["field"]
            operand = self._gen_expr(value["args"][0])
            op = "=" if act == "set_state" else "+="
            return f"() => {{ this.state.{field} {op} {operand}; }}"

        if kind == "sso":
            args = [self._gen_expr(a) for a in value["args"]]
            return f"Workpeg.ssoApprove({', '.join(args)})"

        if kind == "http":
            args = [self._gen_expr(a) for a in value["args"]]
            method = value["method"]
            if value.get("opts"):
                # Every helper is (url, data, opts): a GET has no data, so its
                # options ride third with an explicit gap, and the runtime
                # reads the same position for every method.
                if len(args) == 1:
                    args.append("undefined")
                entries = ", ".join(
                    f"{k}: {self._gen_expr(v)}"
                    for k, v in value["opts"].items())
                args.append(f"{{ {entries} }}")
            # capitalize() lowercases everything after the first character, so
            # a multi-word method comes out as "Postfile" and calls a helper
            # that does not exist. Spell the camelCase name for those.
            helper = "Workpeg.http" + (
                _HTTP_HELPERS.get(method) or method.capitalize())
            return f"{helper}({', '.join(args)})"

        if kind == "workpeg":
            args = [self._gen_expr(a) for a in value["args"]]
            if value.get("opts"):
                entries = ", ".join(
                    f"{k}: {self._gen_expr(v)}"
                    for k, v in value["opts"].items())
                args.append(f"{{ {entries} }}")
            method = value["method"]
            if "_" in method:
                # Tables & Rows sugar (get_tables, add_row, …): snake_case
                # maps to the runtime's Workpeg.wp<CamelCase> helper, which is
                # always protected — no "Protected" suffix to bolt on.
                camel = "".join(p.capitalize() for p in method.split("_"))
                return f"Workpeg.wp{camel}({', '.join(args)})"
            helper = "Workpeg.wp" + method.capitalize()
            if value.get("protected"):
                helper += "Protected"     # sends credentials: "include"
            return f"{helper}({', '.join(args)})"

        if kind == "cookie":
            args = [self._gen_expr(a) for a in value["args"]]
            return f"Workpeg.getCookie({', '.join(args)})"

        raise ValueError(f"Unknown expression kind: {kind}")

    def _gen_slice_bound(self, node: Any) -> str:
        """Render a slice bound; an omitted bound (None) becomes JS null."""
        if node is None:
            return "null"
        return self._gen_expr(node)

    def _gen_method_call(self, value: dict) -> str:
        """Render a method call on a list/string target.

        Most map straight to a JS array method; a few need a Python-faithful
        shape (join is reversed, count/index/sort have semantics fixes).
        """
        name = value["name"]
        target = self._gen_receiver(value["target"])
        # .filter/.some/.every decide by JS truthiness, but their predicate is
        # a Python expression — an empty list returned from it means False.
        if (name in ("filter", "some", "every") and len(value["args"]) == 1
                and isinstance(value["args"][0], dict)
                and value["args"][0].get("expr") == "lambda"):
            lam = value["args"][0]
            params = ", ".join(lam["params"])
            body = self._gen_test(lam["body"])
            return f"{target}.{name}(({params}) => {body})"
        args = [self._gen_expr(a) for a in value["args"]]

        if name == "join":
            # Python: sep.join(items)  ->  JS: items.join(sep)
            return f"{self._gen_receiver(value['args'][0])}.join({target})"
        if name == "index":
            return f"{target}.indexOf({args[0]})"
        if name == "count":
            return f"Workpeg.count({target}, {args[0]})"
        if name == "extend":
            return f"{target}.push(...{args[0]})"
        if name == "sort":
            # Python sorts numbers numerically; JS default is lexicographic.
            return f"{target}.sort(Workpeg.cmp)"
        if name == "clear":
            return f"{target}.splice(0)"
        if name == "remove":
            return f"{target}.splice({target}.indexOf({args[0]}), 1)"
        if name == "lower":
            return f"{target}.toLowerCase()"
        if name == "upper":
            return f"{target}.toUpperCase()"
        if name == "strip":
            return f"{target}.trim()"

        # Direct passthrough: append->push handled by parser name remap;
        # push/pop/shift/unshift/reverse/find/some/every/map/filter/
        # reduce/flatMap/concat keep their JS names.
        joined = ", ".join(args)
        return f"{target}.{name}({joined})"

    #: Builtins that consume an ITERABLE. Python iterates a dict's keys, so
    #: each of these must see what `for` would walk — otherwise sorted(d) and
    #: list(d) evaluate to [] and sum(d) throws, all silently.
    _ITERABLE_BUILTINS = frozenset((
        "sorted", "reversed", "sum", "list", "enumerate", "min", "max",
    ))

    def _gen_builtin(self, value: dict) -> str:
        fn = value["fn"]
        args = [self._gen_expr(a) for a in value["args"]]

        # A single-iterable call gets its argument normalised, unless the
        # parser already proved it is an array (a literal, a range, a
        # comprehension chain) and skipped the wrap.
        if (fn in self._ITERABLE_BUILTINS and len(value["args"]) == 1
                and not ASTParser._is_certainly_a_sequence(value["args"][0])):
            args[0] = f"Workpeg.iter({args[0]})"

        if fn == "len":
            return f"Workpeg.len({args[0]})"
        if fn == "sorted":
            return f"Workpeg.sorted({args[0]})"
        if fn == "reversed":
            return f"Workpeg.slice({args[0]}, null, null, -1)"
        if fn == "sum":
            return f"{args[0]}.reduce((_a, _b) => _a + _b, 0)"
        if fn == "list":
            return f"Array.from({args[0]})"
        if fn == "range":
            return f"Workpeg.range({', '.join(args)})"
        if fn == "enumerate":
            return f"{args[0]}.map((_v, _i) => [_i, _v])"
        if fn in ("min", "max"):
            # Single-iterable form only: Math.min/max coerce to number, so the
            # smallest of a list of strings (or of a dict's keys) came back
            # NaN. The multi-argument form min(a, b) stays numeric.
            helper = "minOf" if fn == "min" else "maxOf"
            return f"Workpeg.{helper}({args[0]})"
        if fn == "isarray":
            return f"Array.isArray({args[0]})"

        raise ValueError(f"Unknown builtin: {fn}")

    def _gen_template_parts(self, parts: list) -> str:
        """Render a structured f-string as a JS template literal.

        Literal string parts are escaped for the template-literal context;
        everything else is an expression rendered into an ${...} slot.
        """
        out: list[str] = ["`"]
        for part in parts:
            if isinstance(part, str):
                out.append(_escape_template_text(part))
            else:
                out.append("${" + self._gen_expr(part) + "}")
        out.append("`")
        return "".join(out)

    def _gen_build(self, tree: WidgetIR) -> str:
        lines: list[str] = []
        lines.append("  build() {")
        lines.append(f"    return {self._gen_widget(tree, indent=4)};")
        lines.append("  }")
        return "\n".join(lines)

    def _gen_render(self) -> str:
        # Re-render into this app's own mount element (the shell's outlet for a
        # routed child, else #workpeg-root), so a child re-render never touches
        # the surrounding shell.
        lines: list[str] = []
        lines.append("  render() {")
        lines.append(
            '    const el = this._mountEl '
            '|| document.getElementById("workpeg-root");'
        )
        lines.append("    if (el) Workpeg.mount(this, el);")
        lines.append("  }")
        return "\n".join(lines)

    def _gen_bootstrap(
        self, class_name: str, store: "dict | None" = None,
        theme: "dict | None" = None, translations: "dict | None" = None,
    ) -> str:
        lines: list[str] = []
        lines.append('window.addEventListener("load", function() {')
        if theme is not None:
            lines.append(f"  Workpeg.applyTheme({json.dumps(theme)});")
        if store is not None:
            lines.append(f"  Workpeg.initStore({json.dumps(store)});")
        if translations is not None:
            lines.append(
                f"  Workpeg.initLocale({json.dumps(translations)});"
            )
        lines.append(f"  const app = new {class_name}();")
        lines.append('  const root = document.getElementById("workpeg-root");')
        # Set document.title from this page's title= (else the build default),
        # before mount so a set_title() in on_mount overrides it. Done here, not
        # in mount(), so re-renders never touch it.
        lines.append("  Workpeg._applyTitle(app);")
        lines.append("  if (root) Workpeg.mount(app, root);")
        lines.append("});")
        return "\n".join(lines)

    def _with_extras(self, props_js: str, widget: WidgetIR) -> str:
        """Splice a widget's expression-valued extras — its ``style={...}`` and
        any universal interaction handlers (on_focus / on_key / …) — into its
        already-emitted props object literal. These are real expressions (dynamic
        style values, handler refs or inline arrows), so they can't go through
        json.dumps with the rest of the props."""
        if widget is None:
            return props_js
        entries: list[str] = []
        style = widget.props.get("style")
        if style:
            entries.append(f'"style": {self._gen_style_obj(style)}')
        title = widget.props.get("title")
        if title is not None:
            entries.append(f'"title": {self._gen_expr(title)}')
        # key / visible — BaseWidget's, parsed centrally in _parse_http_call's
        # sibling loop for EVERY widget, so they are emitted here rather than
        # in each widget's own props branch. Without this they parse cleanly
        # and then vanish, which is the worse failure: no error, no effect.
        key = widget.props.get("key")
        if key is not None:
            entries.append(f'"key": {self._gen_expr(key)}')
        visible = widget.props.get("visible")
        if visible is not None:
            entries.append(f'"visible": {self._gen_expr(visible)}')
        for prop in _INTERACTION_EVENT_PROPS:
            handler = widget.props.get(prop)
            if handler is None:
                continue
            entries.append(f"{prop}: {self._handler_js(handler)}")
        if not entries:
            return props_js
        extra = ", ".join(entries)
        body = props_js.strip()
        # Take the literal apart FIRST, then decide, instead of matching the
        # caller's empty-object spelling against a list of known-empty strings.
        # An earlier version tested `body in ("{}", "{ }")` before this splice,
        # which meant every new spelling of "no props" was a fresh leading-comma
        # bug: `_gen_table_cell` joins a possibly-empty entries list into
        # "{ " + "" + " }", i.e. "{  }" with TWO spaces, which that tuple did
        # not cover, so an ordinary spacer cell like TableCell(style=...) or
        # TableCell(key=...) spliced into `{ , "style": ... }` — a SyntaxError
        # that takes down the parse of the entire generated app.js, blanking the
        # whole page rather than one cell. The multi-line callers (image, logo,
        # textinput, …) would evade a string match the same way if their seed
        # entries ever went conditional, since their empty body is "{\n    \n  }".
        # `inner` is the only thing that actually matters: if there is nothing
        # between the braces there is nothing to put a comma after.
        close = body.rfind("}")
        inner = body[1:close].strip().rstrip(",")
        if not inner:
            return "{ " + extra + " }"
        return "{ " + inner + ", " + extra + " }"

    def _gen_style_obj(self, style: dict) -> str:
        """Serialise a parsed ``style`` dict to a JS object literal. An ordinary
        value is an expression IR (which is itself a dict); a ``:state`` key —
        identified by the leading colon, *not* the value type — maps to a nested
        dict of CSS overrides, emitted as a nested object the runtime turns into a
        rule. Every leaf value goes through ``_gen_expr``."""
        pairs = []
        for prop, val in style.items():
            if prop.startswith(":"):           # a :state block → nested object
                inner = ", ".join(
                    f"{json.dumps(p)}: {self._gen_expr(v)}"
                    for p, v in val.items()
                )
                pairs.append(f"{json.dumps(prop)}: {{ {inner} }}")
            else:
                pairs.append(f"{json.dumps(prop)}: {self._gen_expr(val)}")
        return "{ " + ", ".join(pairs) + " }"

    def _gen_canvas(self, widget: WidgetIR, indent: int) -> str:
        """Emit a canvas node: static width/height/background + the draw ops as
        children (the runtime reads, not renders, them)."""
        pad = " " * indent
        p = widget.props
        # Static props go through json.dumps; the freehand `strokes` (a dynamic
        # expression) and `on_change` (a handler) are spliced as real JS. width /
        # height may be a constant int or a dynamic expression (e.g. a viewer
        # sizing the canvas to each page).

        def _size(key, default):
            v = p.get(key, default)
            js = self._gen_expr(v) if isinstance(v, dict) else json.dumps(v)
            return f'"{key}": {js}'
        entries = [_size("width", 300), _size("height", 150)]
        for k, js_key in (("background", "background"), ("pen_color", "penColor"),
                          ("pen_width", "penWidth")):
            if p.get(k) is not None:
                entries.append(f'"{js_key}": {json.dumps(p[k])}')
        if p.get("strokes") is not None:
            entries.append(f'"strokes": {self._gen_expr(p["strokes"])}')
        if p.get("capture") is not None:
            entries.append(f'"capture": {self._gen_expr(p["capture"])}')
        for k, js_key in _CANVAS_HANDLER_KEYS:
            if p.get(k) is not None:
                entries.append(f'"{js_key}": {self._handler_js(p[k])}')
        props_js = "{ " + ", ".join(entries) + " }"
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "canvas",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_canvas_op(self, widget: WidgetIR, indent: int) -> str:
        """Emit a draw op (rect/circle/line/path/canvastext) — each prop value is
        a JS expression so it can be reactive; CanvasText's text is a Text-style
        value. No children (the canvas runtime interprets it, not the DOM)."""
        pad = " " * indent
        t = widget.type.lower()
        entries: list[str] = []
        for key, value in widget.props.items():
            if t == "canvastext" and key == "text":
                val = (self._gen_expr(value) if isinstance(value, dict)
                       else self._text_to_js(value))
            else:
                val = self._gen_expr(value)
            entries.append(f"{json.dumps(key)}: {val}")
        props_js = "{ " + ", ".join(entries) + " }" if entries else "{}"
        if t == "group":
            # a transform op carries child ops (recursively generated)
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n'
                f"{pad}  {children_js}\n{pad})"
            )
        return (
            f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_container(
        self, t: str, props: dict, widget: WidgetIR, indent: int
    ) -> str:
        """Emit a plain container node — ``Workpeg.h(type, props, children)``.
        Shared by column/row/center/align/gridview, which differ only in props."""
        pad = " " * indent
        # `style` and the interaction handlers are emitted by _with_extras (their
        # values are expressions, not JSON), so keep them out of the JSON-dumped
        # props to avoid a duplicate.
        dropped = {"style", "title", *_INTERACTION_EVENT_PROPS}
        props = {k: v for k, v in props.items()
                 if k not in dropped} if props else {}
        props_js = self._with_extras(json.dumps(props) if props else "{}", widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_widget(self, widget: WidgetIR, indent: int = 0) -> str:
        pad = " " * indent
        t = widget.type.lower()

        if t == "conditional":
            return self._gen_conditional(widget, indent)

        if t == "component":
            return self._gen_component_node(widget)

        if t == "slot":
            # A single-child slot — the prop holds the widget node passed in.
            return f"this.{widget.props['name']}"

        if t == "scaffoldslots":
            # The Scaffold's slot handoff: the five host slot roots (nav,
            # fixed, top_nav, main, attached) the runtime renders and the
            # bundled scaffold.js chrome adopts (see Workpeg._scaffoldMount).
            # The chrome draws its OWN glyphs (search, sparkles, chevrons…),
            # so a Scaffold build always links an icon stylesheet even when
            # nothing in the host's tree emits an Icon — otherwise the whole
            # chrome renders glyph-less.
            self.uses_icons = True
            # This app loads chrome at runtime (scaffold.js, and ai.js via the
            # rail's Workpeg AI row), so it's worth warming the CDN connection
            # the loader uses. An app with no Scaffold never fetches either and
            # must not be made to announce itself to the CDN for nothing.
            self.uses_chrome = True
            return self._gen_container("scaffold", {}, widget, indent)

        # Plain flex/grid containers all emit Workpeg.h(type, props, children);
        # they differ only in which props they carry.
        if t == "input":
            return self._gen_input(widget, indent)

        if t in _FIELD_LIBRARY_TYPES:
            # A shipped composition: the SAME node as `input` with a recipe
            # on it, so the runtime fuses the parts from its own table. One
            # emitter for all four — a new library adds a name to the set
            # above, not a branch here.
            return self._gen_field_library(t, widget, indent)

        if t in ("adornment", "demarcation", "dropdown"):
            return self._gen_field_part(t, widget, indent)

        if t in ("column", "row"):
            # Column/Row carry the Flutter-style flex props the runtime reads
            # (crossAxisAlignment, mainAxisAlignment, MainAxisSize, gap, scroll).
            keep = ("align", "justify", "main_axis_size", "gap", "scroll")
            props = {k: widget.props[k] for k in keep if k in widget.props}
            return self._gen_container(t, props, widget, indent)

        if t == "center":
            return self._gen_container(t, {}, widget, indent)

        if t == "align":
            alignment = widget.props.get("alignment", "center")
            return self._gen_container("align", {"alignment": alignment}, widget, indent)

        if t == "padding":
            edges = {s: widget.props.get(s, 0) for s in ("top", "right", "bottom", "left")}
            return self._gen_container("padding", edges, widget, indent)

        if t in ("aspectratio", "constrainedbox", "fractionallysizedbox",
                 "transform", "limitedbox"):
            return self._gen_container(t, dict(widget.props), widget, indent)

        if t in ("intrinsicwidth", "intrinsicheight"):
            return self._gen_container(t, {}, widget, indent)

        if t == "fittedbox":
            return self._gen_container("fittedbox", dict(widget.props), widget, indent)

        if t == "offstage":
            # `offstage` may be a reactive state expression, so emit it as a JS
            # expression rather than a static JSON prop.
            off = self._gen_expr(widget.props.get("offstage", True))
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "offstage",\n{pad}  {{"offstage": {off}}},\n'
                f"{pad}  {children_js}\n{pad})"
            )

        if t == "sizedbox":
            props = {
                k: widget.props[k]
                for k in ("width", "height") if k in widget.props
            }
            return self._gen_container("sizedbox", props, widget, indent)

        if t == "container":
            return self._gen_container("container", dict(widget.props), widget, indent)

        if t in ("expanded", "flexible", "spacer"):
            return self._gen_container(t, {"flex": widget.props.get("flex", 1)}, widget, indent)

        if t == "outlet":
            # The Shell's routed-child slot — an empty marked element the router
            # fills with the active route's app after the shell mounts.
            return self._gen_container("outlet", {}, widget, indent)

        if t == "authenticated":
            # Auth gate — the runtime renders the child only once the session
            # check passes, else a loader / redirect (see Workpeg renderNode).
            return self._gen_container("authenticated", {}, widget, indent)

        if t == "tooltip":
            # The Tooltip widget augments its child with a hover bubble. `text`
            # is a (possibly dynamic) expression; placement/color are static.
            entries = [f"text: {self._gen_expr(widget.props['text'])}"]
            if "placement" in widget.props:
                entries.append(
                    f"placement: {json.dumps(widget.props['placement'])}"
                )
            if "color" in widget.props:
                entries.append(f"color: {json.dumps(widget.props['color'])}")
            props_js = "{ " + ", ".join(entries) + " }"
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "tooltip",\n{pad}  {props_js},\n'
                f"{pad}  {children_js}\n{pad})"
            )

        if t == "resizable":
            # Augments its child with an edge drag-grip (side/min/max are static;
            # an optional key persists the dragged width across re-renders).
            keep = ("side", "min", "max", "key")
            props = {k: widget.props[k] for k in keep if k in widget.props}
            return self._gen_container("resizable", props, widget, indent)

        if t == "modal":
            # An overlay dialog: `open` is a reactive condition; on_close is a
            # bound method (backdrop click / Esc); title an optional header.
            p = widget.props
            entries = [f"open: {self._gen_expr(p['open'])}"]
            if p.get("on_close"):
                oc = p["on_close"]
                entries.append(
                    f"onClose: {self._handler_js(oc)}" if isinstance(oc, dict)
                    else f"onClose: () => this.{oc}()")
            if "title" in p:
                title = p["title"]
                entries.append("title: " + (
                    self._gen_expr(title) if isinstance(title, dict)
                    else self._text_to_js(title)))
            if "width" in p:
                entries.append(f"width: {json.dumps(p['width'])}")
            if p.get("flush"):
                entries.append("flush: true")
            props_js = "{ " + ", ".join(entries) + " }"
            child = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "modal",\n{pad}  {props_js},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "drawer":
            # An in-flow side panel that animates its width open: `open` is a
            # reactive condition; on_close a bound method (Esc / the header X);
            # title an optional header; width the open panel width (px).
            p = widget.props
            entries = [f"open: {self._gen_expr(p['open'])}"]
            if p.get("on_close"):
                oc = p["on_close"]
                entries.append(
                    f"onClose: {self._handler_js(oc)}" if isinstance(oc, dict)
                    else f"onClose: () => this.{oc}()")
            if "title" in p:
                title = p["title"]
                entries.append("title: " + (
                    self._gen_expr(title) if isinstance(title, dict)
                    else self._text_to_js(title)))
            if "width" in p:
                entries.append(f"width: {json.dumps(p['width'])}")
            props_js = "{ " + ", ".join(entries) + " }"
            child = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "drawer",\n{pad}  {props_js},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "menu":
            # A trigger (first child) + a dropdown panel (the rest); placement is
            # the side it opens toward. `lazy` defers building the panel to the
            # first open. Open/close is wired in the runtime.
            menu_props = {"placement": widget.props.get("placement", "bottom")}
            if widget.props.get("lazy"):
                menu_props["lazy"] = True
            props_js = json.dumps(menu_props)
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "menu",\n{pad}  {props_js},\n'
                f"{pad}  {children_js}\n{pad})"
            )

        if t == "tabs":
            return self._gen_tabs(widget, indent)

        if t == "accordion":
            return self._gen_accordion(widget, indent)

        if t == "spinner":
            return self._gen_spinner(widget, indent)

        if t == "progress":
            return self._gen_progress(widget, indent)

        if t == "divider":
            return self._gen_divider(widget, indent)

        if t == "listtile":
            return self._gen_list_tile(widget, indent)

        if t == "tablecell":
            return self._gen_table_cell(widget, indent)

        if t == "badge":
            return self._gen_badge(widget, indent)

        if t == "chip":
            return self._gen_chip(widget, indent)

        if t == "tag":
            return self._gen_tag(widget, indent)

        if t == "wizard":
            return self._gen_wizard(widget, indent)
        if t == "pill":
            return self._gen_pill(widget, indent)

        if t == "form":
            return self._gen_form(widget, indent)

        if t == "field":
            return self._gen_field(widget, indent)

        if t in ("futurebuilder", "streambuilder"):
            return self._gen_async_builder(widget, indent, t)

        if t == "stack":
            alignment = widget.props.get("alignment", "top_left")
            return self._gen_container("stack", {"alignment": alignment}, widget, indent)

        if t == "wrap":
            props = {
                "spacing": widget.props.get("spacing", 8),
                "run_spacing": widget.props.get("run_spacing", 8),
                "direction": widget.props.get("direction", "horizontal"),
            }
            if "cross_alignment" in widget.props:
                props["cross_alignment"] = widget.props["cross_alignment"]
            return self._gen_container("wrap", props, widget, indent)

        if t == "positioned":
            offsets = {
                k: widget.props[k] for k in
                ("top", "right", "bottom", "left", "width", "height")
                if k in widget.props
            }
            return self._gen_container("positioned", offsets, widget, indent)

        if t == "gridview":
            props = {"columns": widget.props.get("columns", 2)}
            if "gap" in widget.props:
                props["gap"] = widget.props["gap"]
            if widget.props.get("padding") is not None:
                props["padding"] = widget.props["padding"]
            return self._gen_container("gridview", props, widget, indent)

        if t == "table":
            # An ALLOWLIST of the props the runtime reads, the way column/row
            # do it — not `dict(widget.props)`. The generic keyword loop puts
            # `visible` and `key` in props for every widget, and `_with_extras`
            # emits both again as real expressions; passing the whole dict
            # therefore json-dumps the raw IR expression OBJECT beside the
            # working one. The right value wins because it is appended last,
            # so it renders correctly and quietly ships nonsense in the bundle.
            keep = ("columns", "header", "dividers", "hover", "density",
                    "height", "resize_x", "resize_y", "resizable",
                    "min_col", "max_col", "border", "clip",
                    "sortable", "search", "search_placeholder", "page_size")
            props = {k: widget.props[k] for k in keep if k in widget.props}
            # `toolbar` / `footer` are nested WidgetIR and CANNOT go through
            # `json.dumps` — adding either to `keep` above is the tempting
            # one-liner and it is a hard build failure ("Object of type
            # WidgetIR is not JSON serializable"). They are spliced as
            # expressions instead, the way `dismissible` splices
            # `background`.
            bars = [name for name in ("toolbar", "footer")
                    if name in widget.props]
            if not bars:
                return self._gen_container("table", props, widget, indent)
            pad = " " * indent
            # The JSON object's INNER text, so the widget entries can join it
            # as siblings. `_with_extras` then takes the whole literal apart
            # again and re-splices `style`/`key`/`visible`/`title`/the
            # interaction handlers — omit that call and every one of them
            # parses cleanly and silently vanishes, which is the worse
            # failure of the two.
            entries = []
            scalars = json.dumps(props)[1:-1].strip() if props else ""
            if scalars:
                entries.append(scalars)
            for name in bars:
                entries.append(
                    f"{name}: {self._gen_widget(widget.props[name], indent + 2)}")
            props_js = self._with_extras("{ " + ", ".join(entries) + " }",
                                         widget)
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "table",\n{pad}  {props_js},\n'
                f"{pad}  {children_js}\n{pad})"
            )

        if t == "canvas":
            return self._gen_canvas(widget, indent)

        if t in ("rect", "circle", "ellipse", "arc", "line", "path",
                 "canvastext", "canvasimage", "group"):
            return self._gen_canvas_op(widget, indent)

        if t == "listview":
            return self._gen_listview(widget, indent)

        if t == "text":
            value = widget.props.get("value", "")
            # Complex f-strings arrive as structured template nodes;
            # plain strings and compact templates go through _text_to_js.
            if isinstance(value, dict):
                js_value = self._gen_expr(value)
            else:
                js_value = self._text_to_js(value)
            # variant, tone and weight are all plain validated literals — the
            # parser has already refused anything not in the allowed set, so
            # json.dumps is enough and none of them can carry an expression.
            style_entries = [
                f"{name}: {json.dumps(widget.props[name])}"
                for name in ("variant", "tone", "weight")
                if widget.props.get(name) is not None
            ]
            props_js = (
                "{}" if not style_entries
                else "{ " + ", ".join(style_entries) + " }"
            )
            props_js = self._with_extras(props_js, widget)
            return (
                f'Workpeg.h(\n{pad}  "text",\n{pad}  {props_js},\n'
                f"{pad}  {js_value}\n{pad})"
            )

        if t == "locale":
            return self._gen_locale(widget, indent)

        if t == "image":
            return self._gen_image(widget, indent)

        if t == "logo":
            return self._gen_logo(widget, indent)

        if t == "gravatarimage":
            return self._gen_gravatar(widget, indent)

        if t in ("cameraview", "screenshare"):
            return self._gen_media_view(t, widget, indent)

        if t == "fileupload":
            return self._gen_file_upload(widget, indent)

        if t == "video":
            return self._gen_video(widget, indent)

        if t == "audio":
            return self._gen_stream_media("audio", widget, indent)

        if t == "fileview":
            return self._gen_fileview(widget, indent)

        if t == "code":
            return self._gen_code(widget, indent)

        if t == "markdown":
            return self._gen_markdown(widget, indent)

        if t == "htmlview":
            return self._gen_html_view(widget, indent)

        if t == "icon":
            return self._gen_icon(widget, indent)

        if t == "textinput":
            return self._gen_textinput(widget, indent)

        if t == "chatinput":
            return self._gen_chat_input(widget, indent)

        if t == "editabletext":
            return self._gen_editable_text(widget, indent)

        if t == "checkbox":
            return self._gen_checkbox(widget, indent)

        if t == "switch":
            return self._gen_switch(widget, indent)

        if t == "togglebutton":
            return self._gen_toggle_button(widget, indent)

        if t == "togglegroup":
            return self._gen_toggle_group(widget, indent)

        if t == "dot":
            return self._gen_dot(widget, indent)

        if t == "buttongroup":
            return self._gen_button_group(widget, indent)

        if t == "calendarcard":
            return self._gen_calendar_card(widget, indent)

        if t in ("calendardatepicker", "calendardaterangepicker",
                 "yearpicker", "timepicker", "datesegments"):
            return self._gen_calendar(widget, indent)

        if t in ("select", "radiogroup"):
            return self._gen_choice_input(widget, indent, t)

        if t == "textarea":
            return self._gen_textarea(widget, indent)

        if t == "markdowneditor":
            return self._gen_markdowneditor(widget, indent)

        if t == "slider":
            return self._gen_slider(widget, indent)

        if t == "draggable":
            child = self._gen_children(widget.children, indent + 2)
            data = self._value_js(widget.props.get("data", ""))
            return (
                f'Workpeg.h(\n{pad}  "draggable",\n{pad}  {{ data: {data} }},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "droptarget":
            child = self._gen_children(widget.children, indent + 2)
            handler = widget.props.get("on_drop")
            entries = []
            if handler:
                entries.append(f"onDrop: {self._handler_js(handler)}")
            props_js = "{ " + ", ".join(entries) + " }" if entries else "{}"
            return (
                f'Workpeg.h(\n{pad}  "droptarget",\n{pad}  {props_js},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "gesturedetector":
            child = self._gen_children(widget.children, indent + 2)
            entries = [
                f"{name}: {self._handler_js(widget.props[name])}"
                for name in _GESTURE_PROPS if name in widget.props
            ]
            props_js = "{ " + ", ".join(entries) + " }"
            return (
                f'Workpeg.h(\n{pad}  "gesturedetector",\n{pad}  {props_js},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "dismissible":
            child = self._gen_children(widget.children, indent + 2)
            p = widget.props
            entries = [
                f"key: {self._value_js(p['key'])}",
                f"onDismissed: {self._handler_js(p['onDismissed'])}",
                f'direction: {self._value_js(p.get("direction", "horizontal"))}',
                f"threshold: {float(p.get('threshold', 0.4))}",
            ]
            if "background" in p:
                entries.append(
                    f"background: {self._gen_widget(p['background'], indent + 2)}")
            inner = f",\n{pad}    ".join(entries)
            props_js = f"{{\n{pad}    {inner}\n{pad}  }}"
            return (
                f'Workpeg.h(\n{pad}  "dismissible",\n{pad}  {props_js},\n'
                f"{pad}  {child}\n{pad})"
            )

        if t == "__each":
            # A spread widget comprehension → ...iter[.filter(...)].map(x => W).
            # The leading spread flattens it into the surrounding children array.
            p = widget.props
            params = ", ".join(p["params"])
            src = self._gen_expr(p["iter"])
            if p["cond"] is not None:
                src = (f"{src}.filter(({params}) => "
                       f"{self._gen_test(p['cond'])})")
            elt_js = self._gen_widget(p["elt"], indent)
            return f"...{src}.map(({params}) => {elt_js})"

        if t == "__each_row":
            # A Table row comprehension. flatMap, not map: a row contributes N
            # CELLS to the grid's flat row-major children, so mapping would
            # nest an array per row and the table would see one child instead
            # of its columns.
            p = widget.props
            params = ", ".join(p["params"])
            src = self._gen_expr(p["iter"])
            if p["cond"] is not None:
                src = (f"{src}.filter(({params}) => "
                       f"{self._gen_test(p['cond'])})")
            cells = ", ".join(self._gen_widget(c, indent) for c in p["cells"])
            return f"...{src}.flatMap(({params}) => [{cells}])"

        if t == "__spread":
            # *expr (e.g. a component's *children slot) → spread the existing
            # array of widget nodes into the surrounding children array.
            return f"...{self._gen_expr(widget.props['iter'])}"

        if t == "button":
            entries = [f"label: {self._value_js(widget.props.get('label', ''))}"]
            handler = widget.props.get("handler")
            if handler:
                # A lambda → an inline arrow closing over loop vars/this; a
                # method-ref name → resolved against the owner at render time.
                entries.append(f"handler: {self._handler_js(handler)}")
            if "variant" in widget.props:
                entries.append(f"variant: {json.dumps(widget.props['variant'])}")
            if "size" in widget.props:
                entries.append(f"size: {json.dumps(widget.props['size'])}")
            if widget.props.get("error"):
                entries.append("error: true")
            if "rounded" in widget.props:
                # `rounded: false` too, when written: a ButtonGroup hands its
                # `rounded` to every button that does not set its own, and a
                # button that said False has set its own.
                entries.append(
                    f"rounded: {'true' if widget.props['rounded'] else 'false'}")
            if widget.props.get("dot"):
                entries.append("dot: true")
            if "ariaLabel" in widget.props:
                entries.append(f"ariaLabel: {json.dumps(widget.props['ariaLabel'])}")
            if widget.props.get("fullWidth"):
                entries.append("fullWidth: true")
            if widget.props.get("kind") == "submit":
                entries.append('kind: "submit"')
            if widget.props.get("disabled"):
                entries.append("disabled: true")
            if "icon" in widget.props:
                self.uses_icons = True
                entries.append(f"icon: {self._value_js(widget.props['icon'])}")
                if widget.props.get("iconPosition"):
                    entries.append(
                        f"iconPosition: {json.dumps(widget.props['iconPosition'])}"
                    )
            props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
            return (
                f'Workpeg.h(\n{pad}  "button",\n{pad}  {props_js},\n'
                f"{pad}  []\n{pad})"
            )

        if t == "link":
            # label and href may be dynamic (state/route refs, f-strings); the
            # rest of the runtime reads them as plain strings at render time. A
            # Link may instead carry widget children (rendered inside the anchor)
            # — then there's no text label.
            entries = []
            if not widget.children:
                entries.append(
                    f"label: {self._value_js(widget.props.get('label', ''))}"
                )
            entries.append(f"href: {self._value_js(widget.props.get('href', '#'))}")
            if "target" in widget.props:
                entries.append(f"target: {json.dumps(widget.props['target'])}")
            if "ariaLabel" in widget.props:
                entries.append(f"ariaLabel: {json.dumps(widget.props['ariaLabel'])}")
            if "icon" in widget.props:
                self.uses_icons = True
                entries.append(f"icon: {self._value_js(widget.props['icon'])}")
            props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
            children_js = self._gen_children(widget.children, indent + 2)
            return (
                f'Workpeg.h(\n{pad}  "link",\n{pad}  {props_js},\n'
                f"{pad}  {children_js}\n{pad})"
            )

        raise ValueError(f"Unknown widget type in JS generator: {widget.type}")

    def _gen_image(self, widget: WidgetIR, indent: int) -> str:
        """Render an image node.

        ``src`` and ``alt`` may be dynamic (strings, compact templates, or
        expression nodes); the rest are plain constants. ``alt``, ``fit``,
        and ``lazy`` are always emitted so the runtime has accessible,
        predictable defaults.
        """
        pad = " " * indent
        props = widget.props
        entries: list[str] = [
            f"src: {self._value_js(props.get('src', ''))}",
            f"alt: {self._value_js(props.get('alt', ''))}",
            f"fit: {json.dumps(props.get('fit', 'cover'))}",
            f"lazy: {json.dumps(props.get('lazy', True))}",
        ]
        for name in ("width", "height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")

        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "image",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_logo(self, widget: WidgetIR, indent: int) -> str:
        """Render a logo node — the runtime builds the CDN src from the
        namespace (host-derived, or the optional override) + variant + theme.
        ``alt`` / ``namespace`` may be dynamic; the rest are constants."""
        pad = " " * indent
        props = widget.props
        # The 404 fallback renders a Tabler bang icon, so the build must pull in
        # the icons stylesheet.
        self.uses_icons = True
        entries: list[str] = [
            f"variant: {json.dumps(props.get('variant', 'primary'))}",
            f"theme: {json.dumps(props.get('theme', 'automatic'))}",
            f"alt: {self._value_js(props.get('alt', ''))}",
            f"fit: {json.dumps(props.get('fit', 'contain'))}",
            f"lazy: {json.dumps(props.get('lazy', True))}",
        ]
        for name in ("width", "height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")

        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "logo",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_gravatar(self, widget: WidgetIR, indent: int) -> str:
        """Render a gravatar avatar node. ``email`` / ``initials`` / ``bg`` /
        ``color`` / ``alt`` may be dynamic; sizing is constant."""
        pad = " " * indent
        props = widget.props
        entries: list[str] = [
            f"email: {self._value_js(props.get('email', ''))}",
            f"initials: {self._value_js(props.get('initials', ''))}",
            f"bg: {self._value_js(props.get('bg', ''))}",
            f"color: {self._value_js(props.get('color', ''))}",
            f"alt: {self._value_js(props.get('alt', ''))}",
            f"fit: {json.dumps(props.get('fit', 'cover'))}",
        ]
        for name in ("width", "height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")

        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "gravatarimage",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_media_view(self, t: str, widget: WidgetIR, indent: int) -> str:
        """Render a CameraView / ScreenShare node — a live <video> bound to a
        camera or screen stream. Sizing is constant; on_error / on_end are
        handlers (method ref or lambda)."""
        pad = " " * indent
        props = widget.props
        entries: list[str] = [f"fit: {json.dumps(props.get('fit', 'cover'))}"]
        if "label" in props:
            entries.append(f"label: {self._value_js(props['label'])}")
        for name in ("width", "height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        if "facing" in props:
            entries.append(f"facing: {json.dumps(props['facing'])}")
        if props.get("audio"):
            entries.append("audio: true")
        if "onError" in props:
            entries.append(f"onError: {self._handler_js(props['onError'])}")
        if "onEnd" in props:
            entries.append(f"onEnd: {self._handler_js(props['onEnd'])}")
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_file_upload(self, widget: WidgetIR, indent: int) -> str:
        """Render a FileUpload node — a click/drop file picker. ``label`` may be
        dynamic; ``on_select``/``on_error`` are handlers; the rest are constants
        (``accept``/``multiple``/``preview``/``maxSize``/``height``/``radius``)."""
        pad = " " * indent
        props = widget.props
        entries: list[str] = [
            f"multiple: {json.dumps(bool(props.get('multiple', False)))}",
            f"preview: {json.dumps(bool(props.get('preview', True)))}",
        ]
        if "label" in props:
            entries.append(f"label: {self._value_js(props['label'])}")
        if "accept" in props:
            entries.append(f"accept: {json.dumps(props['accept'])}")
        if "maxSize" in props:
            entries.append(f"maxSize: {json.dumps(props['maxSize'])}")
        if props.get("disabled"):
            entries.append("disabled: true")
        for name in ("height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        if "onSelect" in props:
            entries.append(f"onSelect: {self._handler_js(props['onSelect'])}")
        if "onError" in props:
            entries.append(f"onError: {self._handler_js(props['onError'])}")
        if "key" in props:
            entries.append(f"key: {json.dumps(props['key'])}")
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "fileupload",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_video(self, widget: WidgetIR, indent: int) -> str:
        """Render a video node — ``src``/``poster`` may be dynamic; the playback
        flags and sizing are constants. A stream video is the other shape
        (:meth:`_gen_stream_media`)."""
        if "src_object" in widget.props:
            return self._gen_stream_media("video", widget, indent)
        pad = " " * indent
        props = widget.props
        entries: list[str] = [
            f"src: {self._value_js(props.get('src', ''))}",
            f"controls: {json.dumps(props.get('controls', True))}",
            f"autoplay: {json.dumps(props.get('autoplay', False))}",
            f"loop: {json.dumps(props.get('loop', False))}",
            f"muted: {json.dumps(props.get('muted', False))}",
        ]
        if "poster" in props:
            entries.append(f"poster: {self._value_js(props['poster'])}")
        for name in ("width", "height", "radius"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "video",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_stream_media(self, t: str, widget: WidgetIR, indent: int) -> str:
        """A ``Video(src_object=)`` or an ``Audio``: ``src_object`` is the
        page's expression for a stream handle, which the runtime hands to
        rtc.js; it is never a URL, so it is written without the media URL
        check a ``src`` goes through. ``controls`` and ``muted`` are always
        written as booleans (an Audio's are false), which the runtime's hook
        sets as they are; a video's box is its style (the parser's
        ``_box_a_stream_video``), spliced in by ``_with_extras``. ``t`` is
        one of the two node types, chosen by the caller and never read from
        the source. ``site`` is the parser's number for the call site,
        ``<type>-<n>``, which the runtime keeps the element by under the
        stream; the IR is not trusted to carry one, so any other value
        raises."""
        assert t in ("video", "audio"), t
        pad = " " * indent
        props = widget.props
        site = props.get("site")
        if not (isinstance(site, str) and re.fullmatch(rf"{t}-[1-9][0-9]*", site)):
            raise ValueError(f"not a {t} site the compiler numbers: {site!r}")
        entries = [
            f"src_object: {self._gen_expr(props['src_object'])}",
            f"site: {json.dumps(site)}",
            f"controls: {json.dumps(bool(props.get('controls', False)))}",
            f"muted: {json.dumps(bool(props.get('muted', False)))}",
        ]
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_fileview(self, widget: WidgetIR, indent: int) -> str:
        """Render a FileView node — fetches a file and shows its contents (text
        or hex). ``src`` may be dynamic; mode/height/max_bytes/radius are
        constants."""
        pad = " " * indent
        props = widget.props
        entries = [f"src: {self._value_js(props.get('src', ''))}"]
        if "mode" in props:
            entries.append(f"mode: {json.dumps(props['mode'])}")
        for name, js_key in (("height", "height"), ("radius", "radius"),
                             ("max_bytes", "maxBytes")):
            if name in props:
                entries.append(f"{js_key}: {json.dumps(props[name])}")
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "fileview",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_code(self, widget: WidgetIR, indent: int) -> str:
        """Render a code node — the text (which may be dynamic) is emitted like a
        Text value and set as textContent (never parsed as HTML)."""
        pad = " " * indent
        value = widget.props.get("value", "")
        js_value = (self._gen_expr(value) if isinstance(value, dict)
                    else self._text_to_js(value))
        inline = json.dumps(widget.props.get("inline", False))
        entries = f"inline: {inline}"
        if widget.props.get("copyable"):
            entries += ", copyable: true"
        props_js = self._with_extras(f"{{ {entries} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "code",\n{pad}  {props_js},\n'
            f"{pad}  {js_value}\n{pad})"
        )

    def _gen_markdown(self, widget: WidgetIR, indent: int) -> str:
        """Render a markdown node — the (possibly dynamic) text is the child; the
        runtime parses it and builds the result from safe DOM (never innerHTML)."""
        pad = " " * indent
        value = widget.props.get("value", "")
        js_value = (self._gen_expr(value) if isinstance(value, dict)
                    else self._text_to_js(value))
        props_js = self._with_extras("{}", widget)
        return (
            f'Workpeg.h(\n{pad}  "markdown",\n{pad}  {props_js},\n'
            f"{pad}  {js_value}\n{pad})"
        )

    def _gen_icon(self, widget: WidgetIR, indent: int) -> str:
        """Render an Icon node — ``<i class="ti ti-NAME">``. Records that the
        build uses icons (so the icon stylesheet gets linked). ``name`` is a
        validated constant; ``size`` is constant; ``color`` may be dynamic."""
        self.uses_icons = True
        pad = " " * indent
        props = widget.props
        entries = [f"name: {self._value_js(props['name'])}"]
        if "size" in props:
            entries.append(f"size: {json.dumps(props['size'])}")
        if "color" in props:
            entries.append(f"color: {self._value_js(props['color'])}")
        if "weight" in props:
            w = props["weight"]
            entries.append(
                "weight: " + (self._gen_expr(w) if isinstance(w, dict)
                              else json.dumps(w)))
        if "key" in props:
            entries.append(f"key: {json.dumps(props['key'])}")
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "icon",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_html_view(self, widget: WidgetIR, indent: int) -> str:
        """Render an HtmlView node — the (possibly dynamic) HTML is the child;
        the runtime parses + sanitises it into safe DOM (never innerHTML)."""
        pad = " " * indent
        value = widget.props.get("value", "")
        js_value = (self._gen_expr(value) if isinstance(value, dict)
                    else self._text_to_js(value))
        props_js = self._with_extras("{}", widget)
        return (
            f'Workpeg.h(\n{pad}  "htmlview",\n{pad}  {props_js},\n'
            f"{pad}  {js_value}\n{pad})"
        )

    def _input_tail_entries(self, props: dict) -> list[str]:
        """The prop tail every input-family widget shares — flags, value
        callbacks, and the caret-restore ``key`` — emitted only when present,
        in one fixed order. One emitter for the whole family so a handler-form
        change (say, lambda support) can never reach some inputs and miss
        others."""
        entries: list[str] = []
        if props.get("disabled"):
            entries.append("disabled: true")
        if props.get("autofocus"):
            entries.append("autofocus: true")
        for ir_name, js_name in (("on_change", "onChange"),
                                 ("on_submit", "onSubmit")):
            if ir_name in props:
                entries.append(f"{js_name}: {self._handler_js(props[ir_name])}")
        if "key" in props:
            entries.append(f"key: {json.dumps(props['key'])}")
        return entries

    def _gen_chat_input(self, widget: WidgetIR, indent: int) -> str:
        """Render a chat-input node — a contenteditable composer. ``value`` is a
        controlled binding; handler names + sizing are constants."""
        pad = " " * indent
        props = widget.props
        entries: list[str] = [f"value: {self._value_js(props.get('value', ''))}"]
        if "placeholder" in props:
            entries.append(f"placeholder: {json.dumps(props['placeholder'])}")
        for key, js_key in (("min_rows", "minRows"), ("max_rows", "maxRows")):
            if key in props:
                entries.append(f"{js_key}: {json.dumps(props[key])}")
        if props.get("markdown"):
            entries.append("markdown: true")
        entries.extend(self._input_tail_entries(props))
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "chatinput",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_editable_text(self, widget: WidgetIR, indent: int) -> str:
        """Render an edit-in-place contenteditable node.

        Ends with :meth:`_input_tail_entries` like every other input — that
        one emitter is what keeps ``disabled`` / ``autofocus`` / ``onChange``
        / ``onSubmit`` / ``key`` identical across the family, so a change to
        the handler form cannot reach some inputs and miss others.
        """
        pad = " " * indent
        props = widget.props
        entries: list[str] = [f"value: {self._value_js(props.get('value', ''))}"]
        if "placeholder" in props:
            entries.append(f"placeholder: {json.dumps(props['placeholder'])}")
        if props.get("multiline"):
            entries.append("multiline: true")
        # `fill` defaults ON, so it is emitted only when switched off — the
        # same shape `dividers` uses on Table.
        if props.get("fill") is False:
            entries.append("fill: false")
        entries.extend(self._input_tail_entries(props))
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "editabletext",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_input(self, widget: WidgetIR, indent: int) -> str:
        """The field container: its props, then its fused parts as children.

        NOT `_gen_container`, which JSON-dumps its props — right for a
        Column's constants and wrong for text that can be state. Through it,
        ``message=self.err`` reached the runtime as a raw IR object, a
        Component's ``label=self.label`` rendered "[object Object]", and an
        f-string label showed its literal ``${name}``. The text props go
        through ``_value_js`` here, exactly as the libraries' and Select's
        already did, so the three field surfaces read one value one way.

        ``value`` is the composite's value for a surrounding ``Field`` — see
        ``Workpeg._fieldValue`` — and is emitted only when given, because its
        presence is what tells the runtime the Input speaks for the field.
        """
        pad = " " * indent
        props = widget.props
        if "status" in props:
            self.uses_icons = True          # the status glyph is an icon
        entries: list[str] = []
        for name in ("label", "hint", "message", "value"):
            if name in props:
                entries.append(f"{name}: {self._value_js(props[name])}")
        for name in ("status", "size", "gap"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        if props.get("disabled"):
            entries.append("disabled: true")
        body = f"{{ {', '.join(entries)} }}" if entries else "{}"
        props_js = self._with_extras(body, widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "input",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_field_library(self, t: str, widget: WidgetIR,
                           indent: int) -> str:
        """A shipped field composition — phone, money, link, card.

        Emitted as the `input` node type with a `recipe`, so the runtime has
        ONE field builder and the libraries are data inside it.
        """
        pad = " " * indent
        props = widget.props
        # Phone and money fuse a picker (a chevron glyph), a date recipe's
        # parts open a calendar (chevrons) or a wheel from a clock unless
        # `picker=False` says not, and any field with a status draws its
        # glyph from the icon font too.
        if t in ("phoneinput", "moneyinput") or "status" in props or (
                t in _DATE_FIELD_TYPES and props.get("picker") is not False):
            self.uses_icons = True
        entries: list[str] = [f'recipe: {json.dumps(t)}']
        if t in _DATE_FIELD_TYPES:
            # The field's own text and axes, then the segments' keywords
            # (value, on_change and disabled among them) as a DateSegments
            # node carries them, mode, site and kind first.
            for name in ("label", "hint", "message"):
                if name in props:
                    entries.append(f"{name}: {self._value_js(props[name])}")
            for name in ("status", "size"):
                if name in props:
                    entries.append(f"{name}: {json.dumps(props[name])}")
            if "on_submit" in props:
                entries.append(
                    f"onSubmit: {self._handler_js(props['on_submit'])}")
            entries.extend(self._calendar_entries(
                props, indent, skip=("label", "hint", "message", "status",
                                     "size", "on_submit")))
            inner = f",\n{pad}    ".join(entries)
            props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}",
                                         widget)
            return (f'Workpeg.h(\n{pad}  "input",\n{pad}  {props_js},\n'
                    f"{pad}  []\n{pad})")
        for name in ("value", "placeholder", "label", "hint", "message"):
            if name in props:
                entries.append(f"{name}: {self._value_js(props[name])}")
        for name in ("status", "size"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        for name in _FIELD_LIBRARY_PROPS:
            if name in props:
                entries.append(f"{name}: {self._value_js(props[name])}")
        if props.get("disabled"):
            entries.append("disabled: true")
        for name, js_name in (("on_change", "onChange"),
                              ("on_submit", "onSubmit")):
            if name in props:
                entries.append(f"{js_name}: {self._handler_js(props[name])}")
        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "input",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_field_part(self, t: str, widget: WidgetIR, indent: int) -> str:
        """One part fused into a field: adornment, demarcation, dropdown."""
        pad = " " * indent
        props = widget.props
        if t == "dropdown":
            # The runtime draws the picker's chevron, search glass and tick
            # as icon-font glyphs. Nothing asked for the icon stylesheet on
            # their behalf, so in an app with no other Icon the trigger had
            # no chevron and the search row no glass.
            self.uses_icons = True
        entries: list[str] = []
        for name in ("text", "value", "placeholder"):
            if name in props:
                entries.append(f"{name}: {self._value_js(props[name])}")
        if "options" in props:
            entries.append(f"options: {self._value_js(props['options'])}")
        if props.get("search"):
            entries.append("search: true")
        if "panel_width" in props:
            entries.append(f"panelWidth: {json.dumps(props['panel_width'])}")
        if "trigger" in props:
            entries.append(f"trigger: {json.dumps(props['trigger'])}")
        if "on_change" in props:
            entries.append(f"onChange: {self._handler_js(props['on_change'])}")
        body = f"{{ {', '.join(entries)} }}" if entries else "{}"
        props_js = self._with_extras(body, widget)
        return (
            f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_textinput(self, widget: WidgetIR, indent: int) -> str:
        """Render a text input node.

        ``value`` is dynamic (a controlled binding to state), and so may
        ``placeholder`` be; the handler names and remaining props are
        constants. ``value`` and ``type`` are always emitted so the runtime
        has predictable defaults.
        """
        pad = " " * indent
        props = widget.props
        entries: list[str] = [
            f"value: {self._value_js(props.get('value', ''))}",
            f"type: {json.dumps(props.get('type', 'text'))}",
        ]
        if "placeholder" in props:
            hint = props["placeholder"]
            # Text through `_value_js`, as `value` is. A non-text constant
            # (``None``, a number) keeps the JSON it always compiled to.
            hint_js = (self._value_js(hint) if isinstance(hint, (str, dict))
                       else json.dumps(hint))
            entries.append(f"placeholder: {hint_js}")
        entries.extend(self._input_tail_entries(props))

        inner = f",\n{pad}    ".join(entries)
        props_js = self._with_extras(f"{{\n{pad}    {inner}\n{pad}  }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "textinput",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_checkbox(self, widget: WidgetIR, indent: int,
                      type_name: str = "checkbox") -> str:
        """Render a checkbox / switch node (same shape). ``checked`` is a bool or
        a dynamic binding; ``label`` is dynamic; ``onChange`` is a handler name."""
        pad = " " * indent
        props = widget.props
        checked = props.get("checked", False)
        checked_js = (
            self._gen_expr(checked) if isinstance(checked, dict)
            else json.dumps(bool(checked))
        )
        entries = [f"checked: {checked_js}"]
        if "label" in props:
            entries.append(f"label: {self._value_js(props['label'])}")
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  {json.dumps(type_name)},\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_switch(self, widget: WidgetIR, indent: int) -> str:
        """Render a switch node — the design's toggle.

        Separate from `_gen_checkbox` because it carries two props a
        checkbox has no meaning for. `size="md"` is the base rule, so it is
        never emitted.
        """
        pad = " " * indent
        props = widget.props
        checked = props.get("checked", False)
        checked_js = (
            self._gen_expr(checked) if isinstance(checked, dict)
            else json.dumps(bool(checked))
        )
        entries = [f"checked: {checked_js}"]
        for key in ("label", "description"):
            if key in props:
                entries.append(f"{key}: {self._value_js(props[key])}")
        size = props.get("size")
        if size and size != "md":
            entries.append(f"size: {json.dumps(size)}")
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "switch",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _entries_node(self, t: str, entries: list, widget: WidgetIR,
                      indent: int) -> str:
        """``Workpeg.h(t, {entries + the central extras}, children)`` — the
        node the toggles and the dot emit. The extras are style, key,
        visible and the interaction events; the children are a toggle's
        content, a group's buttons, or none."""
        pad = " " * indent
        body = "{ " + ", ".join(entries) + " }" if entries else "{}"
        props_js = self._with_extras(body, widget)
        kids = self._gen_children(widget.children, indent + 2)
        return (f'Workpeg.h(\n{pad}  "{t}",\n{pad}  {props_js},'
                f'\n{pad}  {kids}\n{pad})')

    def _gen_toggle_button(self, widget: WidgetIR, indent: int) -> str:
        """Render a toggle button node. Only what was passed is emitted —
        an absent ``variant``/``size`` is how a button inside a group
        inherits the group's, so emitting the default here would break that.
        """
        p = widget.props
        entries = []
        # `selected`, `disabled` and `value` are each a folded literal or a
        # live expression; `_gen_expr` writes either.
        for key in ("selected", "disabled", "value"):
            if key in p:
                entries.append(f"{key}: {self._gen_expr(p[key])}")
        for key in ("variant", "size"):
            if key in p:
                entries.append(f"{key}: {json.dumps(p[key])}")
        if "label" in p:
            entries.append(f"label: {self._value_js(p['label'])}")
        if p.get("on_change"):
            entries.append(f"onChange: {self._handler_js(p['on_change'])}")
        return self._entries_node("togglebutton", entries, widget, indent)

    def _gen_toggle_group(self, widget: WidgetIR, indent: int) -> str:
        """Render a toggle group node — its mode, layout and the defaults it
        hands its buttons. ``managed`` is explicit rather than read off the
        presence of ``value``, because ``value: null`` is a managed group
        with nothing selected and must not read as a visual one."""
        p = widget.props
        entries = []
        if p.get("managed"):
            entries.append("managed: true")
            entries.append(f"value: {self._gen_expr(p.get('value'))}")
        for key, js_key in (("multiple", "multiple"),
                            ("allow_empty", "allowEmpty"),
                            ("fill", "fill"), ("spaced", "spaced")):
            if p.get(key):
                entries.append(f"{js_key}: true")
        if p.get("direction", "horizontal") != "horizontal":
            entries.append(f"direction: {json.dumps(p['direction'])}")
        for key in ("variant", "size"):
            if key in p:
                entries.append(f"{key}: {json.dumps(p[key])}")
        if "disabled" in p:
            entries.append(f"disabled: {self._gen_expr(p['disabled'])}")
        if "label" in p:
            entries.append(f"label: {self._value_js(p['label'])}")
        if p.get("on_change"):
            entries.append(f"onChange: {self._handler_js(p['on_change'])}")
        return self._entries_node("togglegroup", entries, widget, indent)

    def _gen_button_group(self, widget: WidgetIR, indent: int) -> str:
        """Render a button group node: the defaults it hands its buttons,
        its layout and its name. Only what was passed is emitted, so an
        absent ``variant`` or ``size`` leaves each button its own."""
        p = widget.props
        entries = [f"{key}: {json.dumps(p[key])}"
                   for key in ("variant", "size") if key in p]
        entries += [f"{key}: {self._gen_expr(p[key])}"
                    for key in ("rounded", "fill", "disabled") if key in p]
        if "label" in p:
            entries.append(f"label: {self._value_js(p['label'])}")
        return self._entries_node("buttongroup", entries, widget, indent)

    def _gen_calendar_card(self, widget: WidgetIR, indent: int) -> str:
        """Render a calendar card node: ``row`` when it is one (a column is
        the default) and a ``gap`` when one was given."""
        p = widget.props
        entries = []
        if p.get("direction", "column") != "column":
            entries.append(f"direction: {json.dumps(p['direction'])}")
        if "gap" in p:
            entries.append(f"gap: {self._gen_expr(p['gap'])}")
        return self._entries_node("calendarcard", entries, widget, indent)

    def _gen_dot(self, widget: WidgetIR, indent: int) -> str:
        """Render a dot node: an optional colour and nothing else."""
        p = widget.props
        entries = ([f"color: {self._value_js(p['color'])}"]
                   if "color" in p else [])
        return self._entries_node("dot", entries, widget, indent)

    #: The calendar keywords that hold a handler rather than a value.
    _CALENDAR_HANDLERS = ("on_change", "on_displayed_month_changed",
                          "selectable_day_predicate", "event_loader")

    def _gen_calendar(self, widget: WidgetIR, indent: int) -> str:
        """Render a calendar node: one runtime type for every calendar
        picker (a range picker is its ``mode``, "range"), its selection
        ``mode`` and compile-time ``site`` first, then
        each keyword under its Python name — the names the runtime's
        CAL_OPTIONS checks. Only what was passed is emitted; the runtime
        holds the defaults. A YearPicker is its own runtime type, built
        from the same section, a TimePicker ("time") is the `wheel`
        section's and a DateSegments ("segments", with its ``kind``, and
        ``fused`` inside an Input) the `segments` section's, each read
        through the same option table.

        A calendar always draws chevrons, so the page always links its icon
        sheet; the runtime writes their class names whole, which keeps them
        in the build's icon subset. So does a DateSegments whose parts open
        a picker (``picker`` anything but a literal False): its calendar
        has the chevrons and its wheel's opener is a clock. A YearPicker
        and a TimePicker draw none, so they link nothing.
        """
        p = widget.props
        kind = {"year": "yearpicker", "time": "timepicker",
                "segments": "datesegments"}.get(p["mode"], "calendar")
        if kind == "calendar" or (kind == "datesegments"
                                  and p.get("picker") is not False):
            self.uses_icons = True
        return self._entries_node(kind, self._calendar_entries(p, indent),
                                  widget, indent)

    def _calendar_entries(self, p: dict, indent: int,
                          skip: tuple = ()) -> list:
        """A calendar-family node's props as entries: ``mode`` and ``site``
        first, then each keyword under its Python name, a handler as a
        handler, a builder as an arrow, a style as a style object and text
        as text. ``skip`` names props the caller emits itself (a date
        recipe's field surface)."""
        entries = [f"mode: {json.dumps(p['mode'])}",
                   f"site: {json.dumps(p['site'])}"]
        for name, value in p.items():
            if name in ("mode", "site", "style", "key", "visible", "title") \
                    or name in skip or name in _INTERACTION_EVENT_PROPS:
                continue
            if name in self._CALENDAR_HANDLERS:
                js = self._handler_js(value)
            elif name == "day_builder":
                # An arrow the runtime calls with each day's dict, as a
                # lazy ListView calls its builder with each index.
                js = (f"({value['param']}) => "
                      f"{self._gen_widget(value['body'], indent + 4)}")
            elif name in ("day_style", "year_style"):
                js = self._gen_style_obj(value)
            elif name in ("label", "error_format_text", "error_invalid_text"):
                js = self._value_js(value)
            else:
                js = self._gen_expr(value)
            entries.append(f"{name}: {js}")
        return entries

    def _gen_textarea(self, widget: WidgetIR, indent: int) -> str:
        """Render a multi-line text input node — like textinput, but a
        ``<textarea>`` with ``rows`` and no ``onSubmit``."""
        pad = " " * indent
        props = widget.props
        entries = [f"value: {self._value_js(props.get('value', ''))}"]
        if "placeholder" in props:
            entries.append(f"placeholder: {json.dumps(props['placeholder'])}")
        if "rows" in props:
            entries.append(f"rows: {json.dumps(props['rows'])}")
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "textarea",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_markdowneditor(self, widget: WidgetIR, indent: int) -> str:
        """Render a Markdown editor node — the textarea's props plus the
        editor's own sizing, toolbar and frame flags. ``toolbar`` is emitted
        only when it is not the bubble (the runtime's default), and ``frame``
        only when off, so the common case stays as small as a textarea's.
        The parser has already folded ``True`` into ``"fixed"``: what reaches
        the runtime is a name or ``false``, never ``true``."""
        pad = " " * indent
        props = widget.props
        entries = [f"value: {self._value_js(props.get('value', ''))}"]
        if "placeholder" in props:
            entries.append(f"placeholder: {json.dumps(props['placeholder'])}")
        if "min_height" in props:
            entries.append(f"minHeight: {json.dumps(props['min_height'])}")
        toolbar = props.get("toolbar", "bubble")
        if toolbar is False:
            entries.append("toolbar: false")
        elif toolbar != "bubble":
            entries.append(f"toolbar: {json.dumps(toolbar)}")
        if props.get("frame") is False:
            entries.append("frame: false")
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "markdowneditor",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_slider(self, widget: WidgetIR, indent: int) -> str:
        """Render a range slider node. ``value`` is a number or a dynamic
        binding; ``min``/``max``/``step`` are constants; ``onChange`` is a
        handler name (called with the parsed number)."""
        pad = " " * indent
        props = widget.props
        value = props.get("value", props.get("min", 0))
        value_js = (
            self._gen_expr(value) if isinstance(value, dict)
            else json.dumps(value)
        )
        entries = [
            f"value: {value_js}",
            f"min: {json.dumps(props.get('min', 0))}",
            f"max: {json.dumps(props.get('max', 100))}",
            f"step: {json.dumps(props.get('step', 1))}",
        ]
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "slider",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_choice_input(
        self, widget: WidgetIR, indent: int, type_name: str
    ) -> str:
        """Render a choice-over-options node (``select``/``radiogroup``).
        ``options`` is an array expression; ``value`` is the controlled
        selection; ``onChange`` is a handler name."""
        pad = " " * indent
        props = widget.props
        if type_name == "select":
            self.uses_icons = True          # it is a Dropdown: see there
        entries = [f"options: {self._gen_expr(props['options'])}"]
        if "value" in props:
            entries.append(f"value: {self._value_js(props['value'])}")
        # A Select is the field container with the picker as its control, so
        # it carries the container's whole surface. Emitted through the same
        # names the container reads, which is what keeps a Select's `status`
        # and an Input's the same thing rather than two spellings.
        for name in ("placeholder", "label", "hint", "message"):
            if name in props:
                entries.append(f"{name}: {self._value_js(props[name])}")
        for name in ("status", "size"):
            if name in props:
                entries.append(f"{name}: {json.dumps(props[name])}")
        if props.get("search"):
            entries.append("search: true")
        entries.extend(self._input_tail_entries(props))
        props_js = self._with_extras(f"{{ {', '.join(entries)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  {json.dumps(type_name)},\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _value_js(self, value: Any) -> str:
        """Render a string-or-expression prop (src/alt): a structured
        expression dict goes through _gen_expr, everything else through
        _text_to_js (plain string -> JSON, compact template -> literal)."""
        if isinstance(value, dict):
            return self._gen_expr(value)
        return self._text_to_js(value)

    def _handler_js(self, handler: Any) -> str:
        """Render an event-handler prop's value: a lambda (a parsed dict) becomes
        an inline arrow closing over loop vars / ``this``; a method-ref name (a
        str) becomes the name string the runtime resolves on the owner."""
        return (self._gen_expr(handler) if isinstance(handler, dict)
                else json.dumps(handler))

    def _gen_listview(self, widget: WidgetIR, indent: int) -> str:
        """Render a listview node.

        Static mode passes plain styling props and real children.  Builder
        mode adds ``itemCount`` (a constant or a state expression) and a
        ``builder`` arrow function the runtime calls per visible index —
        that's what keeps large lists lazy.
        """
        pad = " " * indent
        entries: list[str] = []
        for ir_name, js_name in _LISTVIEW_PROPS.items():
            if ir_name in widget.props:
                entries.append(
                    f"{js_name}: {self._gen_expr(widget.props[ir_name])}"
                )

        builder = widget.props.get("builder")
        if builder is not None:
            body_js = self._gen_widget(builder["body"], indent + 4)
            entries.append(f"builder: ({builder['param']}) => {body_js}")

        if entries:
            inner = f",\n{pad}    ".join(entries)
            props_js = f"{{\n{pad}    {inner}\n{pad}  }}"
        else:
            props_js = "{}"

        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "listview",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_async_builder(self, widget: WidgetIR, indent: int,
                           type_name: str) -> str:
        """Render a future/stream builder. The slots are emitted as JS values:
        ``future`` an arrow returning a promise, ``done``/``error`` arrows
        returning widget nodes, ``loading`` a node. ``key`` is the cache id."""
        pad = " " * indent
        p = widget.props
        entries = [f"key: {self._value_js(p['key'])}"]
        if type_name == "futurebuilder":
            fut = p["future"]
            if "methodref" in fut:
                entries.append(f'future: () => this.{fut["methodref"]}()')
            else:
                entries.append(f"future: {self._gen_expr(fut['lambda'])}")
        else:
            entries.append(f"stream: {self._value_js(p['stream'])}")
        if "loading" in p:
            entries.append(f"loading: {self._gen_widget(p['loading'], indent + 2)}")
        if "error" in p:
            err = p["error"]
            if "static" in err:
                entries.append(
                    f"error: {self._gen_widget(err['static'], indent + 2)}")
            else:
                entries.append(
                    f'error: ({err["param"]}) => '
                    f"{self._gen_widget(err['body'], indent + 2)}")
        done = p["done"]
        entries.append(
            f'done: ({done["param"]}) => '
            f"{self._gen_widget(done['body'], indent + 2)}")
        inner = f",\n{pad}    ".join(entries)
        props_js = f"{{\n{pad}    {inner}\n{pad}  }}"
        return (
            f'Workpeg.h(\n{pad}  "{type_name}",\n{pad}  {props_js},\n'
            f"{pad}  []\n{pad})"
        )

    def _gen_form(self, widget: WidgetIR, indent: int) -> str:
        """Render a form node — its children (fields + plain widgets) plus the
        ``onSubmit`` handler name the runtime calls when every field validates."""
        pad = " " * indent
        entries: list[str] = []
        if "on_submit" in widget.props:
            entries.append(f"onSubmit: {self._handler_js(widget.props['on_submit'])}")
        if "key" in widget.props:
            entries.append(f"key: {json.dumps(widget.props['key'])}")
        props_js = "{ " + ", ".join(entries) + " }" if entries else "{}"
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "form",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_validators(self, validators: list) -> str:
        """Emit a field's validator descriptors. Built-ins are inert JSON; a
        custom validator's ``fn`` is a lambda — emitted as an inline arrow (the
        rest of the descriptor is still JSON)."""
        parts = []
        for v in validators:
            if v.get("check") == "fn":
                fn = v["fn"]
                if isinstance(fn, dict) and "methodref" in fn:
                    fn_js = f'(v) => this.{fn["methodref"]}(v)'   # self.method
                else:
                    fn_js = self._gen_expr(fn)                    # lambda
                parts.append('{ "check": "fn", "fn": ' + fn_js + " }")
            else:
                parts.append(json.dumps(v))
        return "[" + ", ".join(parts) + "]"

    def _gen_field(self, widget: WidgetIR, indent: int) -> str:
        """Render a field node — name, optional (dynamic) label, the validator
        descriptors (plain JSON — inert), and the wrapped input child."""
        pad = " " * indent
        p = widget.props
        entries = [f"name: {json.dumps(p['name'])}"]
        if p.get("label") is not None:
            entries.append(f"label: {self._value_js(p['label'])}")
        if p.get("validators"):
            entries.append(f"validators: {self._gen_validators(p['validators'])}")
        if "key" in p:
            entries.append(f"key: {json.dumps(p['key'])}")
        props_js = "{ " + ", ".join(entries) + " }"
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "field",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_badge(self, widget: WidgetIR, indent: int) -> str:
        """Render a badge node. ``label`` is dynamic text (textContent); an
        anchored badge carries its ``child`` as the single rendered child."""
        pad = " " * indent
        p = widget.props
        entries: list[str] = []
        if p.get("label") is not None:
            entries.append(f"label: {self._value_js(p['label'])}")
        if p.get("hasChild"):
            entries.append("hasChild: true")
        body = "{ " + ", ".join(entries) + " }" if entries else "{}"
        props_js = self._with_extras(body, widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "badge",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_pill(self, widget: WidgetIR, indent: int) -> str:
        """Render a pill node — the design's `btn--tertiary btn--rounded`."""
        pad = " " * indent
        p = widget.props
        entries = [f"label: {self._value_js(p['label'])}"]
        selected = p.get("selected")
        if isinstance(selected, dict):
            entries.append(f"selected: {self._gen_expr(selected)}")
        elif selected:
            entries.append("selected: true")
        if p.get("size"):
            entries.append(f"size: {json.dumps(p['size'])}")
        for key, js_key in (("on_click", "onClick"),
                            ("on_remove", "onRemove")):
            handler = p.get(key)
            if handler:
                entries.append(f"{js_key}: {self._handler_js(handler)}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        return (
            f'Workpeg.h(\n{pad}  "pill",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_chip(self, widget: WidgetIR, indent: int) -> str:
        """Render a chip node. ``label`` is dynamic text; ``selected`` is a bool
        or binding; ``onClick``/``onDelete`` are handlers (arrow or method name)."""
        pad = " " * indent
        p = widget.props
        entries = [f"label: {self._value_js(p['label'])}"]
        selected = p.get("selected")
        if isinstance(selected, dict):
            entries.append(f"selected: {self._gen_expr(selected)}")
        elif selected:
            entries.append("selected: true")
        for key, js_key in (("on_click", "onClick"), ("on_delete", "onDelete")):
            handler = p.get(key)
            if handler:
                entries.append(f"{js_key}: {self._handler_js(handler)}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        return (
            f'Workpeg.h(\n{pad}  "chip",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_tag(self, widget: WidgetIR, indent: int) -> str:
        """Render a tag node — the design's badge.

        Only the props that differ from the default are emitted, so the
        common `Tag("Label")` stays a two-key object in the bundle instead
        of carrying nine keys of "no". `label` may be dynamic; everything
        else was pinned to a literal by the parser.
        """
        pad = " " * indent
        p = widget.props
        entries = []
        if p.get("label") is not None:
            entries.append(f"label: {self._value_js(p['label'])}")
        for key, default in (("tone", "neutral"), ("size", "md"),
                             ("fill", "subtle")):
            value = p.get(key, default)
            if value != default:
                entries.append(f"{key}: {json.dumps(value)}")
        for key in ("icon", "avatar", "flag"):
            if p.get(key):
                entries.append(f"{key}: {json.dumps(p[key])}")
        for key in ("dot", "arrow"):
            if p.get(key):
                entries.append(f"{key}: true")
        handler = p.get("on_dismiss")
        if handler:
            entries.append(f"onDismiss: {self._handler_js(handler)}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        kids = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "tag",\n{pad}  {props_js},'
            f'\n{pad}  {kids}\n{pad})'
        )

    def _gen_wizard(self, widget: WidgetIR, indent: int) -> str:
        """Render a wizard node — the progress bar's labels plus one panel
        per child. `value` and `onChange` are always present; the parser
        refuses a Wizard without them."""
        pad = " " * indent
        p = widget.props
        labels = ", ".join(self._value_js(la) for la in p.get("labels", []))
        entries = [f"labels: [{labels}]",
                   f"value: {self._gen_expr(p['value'])}"
                   if isinstance(p.get("value"), dict)
                   else f"value: {json.dumps(p.get('value', 0))}",
                   f"onChange: {self._handler_js(p['on_change'])}"]
        if p.get("optional"):
            entries.append(f"optional: {json.dumps(p['optional'])}")
        if "key" in p:
            entries.append(f"key: {json.dumps(p['key'])}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        kids = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "wizard",\n{pad}  {props_js},'
            f'\n{pad}  {kids}\n{pad})'
        )

    def _gen_locale(self, widget: WidgetIR, indent: int) -> str:
        """Render a locale node. ``token``/``fallback`` are text; ``values`` is a
        map of placeholder name -> expression, filled in at render time."""
        pad = " " * indent
        p = widget.props
        entries = [f"token: {self._value_js(p['token'])}"]
        fallback = p.get("fallback")
        if fallback:
            entries.append(f"fallback: {json.dumps(fallback)}")
        variant = p.get("variant")
        if variant is not None:
            entries.append(f"variant: {json.dumps(variant)}")
        values = p.get("values")
        if values:
            pairs = ", ".join(
                f"{json.dumps(name)}: {self._gen_expr(expr)}"
                for name, expr in values.items()
            )
            entries.append(f"values: {{ {pairs} }}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        return (
            f'Workpeg.h(\n{pad}  "locale",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_divider(self, widget: WidgetIR, indent: int) -> str:
        """Render a divider node — only the non-default numeric props; the
        runtime coerces them and writes them via the CSSOM."""
        pad = " " * indent
        p = widget.props
        entries: list[str] = []
        if p.get("vertical"):
            entries.append("vertical: true")
        if p.get("thickness", 1) != 1:
            entries.append(f"thickness: {json.dumps(p['thickness'])}")
        if p.get("spacing", 0):
            entries.append(f"spacing: {json.dumps(p['spacing'])}")
        body = "{ " + ", ".join(entries) + " }" if entries else "{}"
        props_js = self._with_extras(body, widget)
        return (
            f'Workpeg.h(\n{pad}  "divider",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_table_cell(self, widget: WidgetIR, indent: int) -> str:
        """Render one cell. ``title``/``subtext`` are dynamic text set via
        textContent — which is why this cannot go through ``_gen_container``,
        whose ``json.dumps`` would turn an expression into a quoted string of
        its source. Any child widget rides in ``children`` like anywhere else.
        """
        pad = " " * indent
        props = widget.props
        entries = []
        for name in ("label", "sub"):
            if props.get(name) is not None:
                entries.append(f"{name}: {self._value_js(props[name])}")
        if props.get("align"):
            entries.append(f'align: {json.dumps(props["align"])}')
        if props.get("nowrap"):
            entries.append("nowrap: true")
        if props.get("hasChild"):
            entries.append("hasChild: true")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "tablecell",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_list_tile(self, widget: WidgetIR, indent: int) -> str:
        """Render a list-tile node. ``title``/``subtitle`` are dynamic text
        (set via textContent); ``leading``/``trailing`` are child widgets;
        ``onClick`` is a handler (lambda arrow or method name)."""
        pad = " " * indent
        props = widget.props
        entries = [f"title: {self._value_js(props['title'])}"]
        if props.get("subtitle") is not None:
            entries.append(f"subtitle: {self._value_js(props['subtitle'])}")
        if props.get("hasLeading"):
            entries.append("hasLeading: true")
        if props.get("hasTrailing"):
            entries.append("hasTrailing: true")
        handler = props.get("on_click")
        if handler:
            entries.append(f"onClick: {self._handler_js(handler)}")
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "listtile",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_spinner(self, widget: WidgetIR, indent: int) -> str:
        """Render a spinner node — just a size (px); the runtime coerces it."""
        pad = " " * indent
        size = widget.props.get("size", 24)
        props_js = self._with_extras(f"{{ size: {json.dumps(size)} }}", widget)
        return (
            f'Workpeg.h(\n{pad}  "spinner",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_progress(self, widget: WidgetIR, indent: int) -> str:
        """Render a progress node. ``value`` (0–1) may be a literal number or a
        dynamic binding; absent ⇒ indeterminate. The runtime clamps it."""
        pad = " " * indent
        entries: list[str] = []
        value = widget.props.get("value")
        if value is not None:
            v_js = (self._gen_expr(value) if isinstance(value, dict)
                    else json.dumps(value))
            entries.append(f"value: {v_js}")
        body = "{ " + ", ".join(entries) + " }" if entries else "{}"
        props_js = self._with_extras(body, widget)
        return (
            f'Workpeg.h(\n{pad}  "progress",\n{pad}  {props_js},\n{pad}  []\n{pad})'
        )

    def _gen_accordion(self, widget: WidgetIR, indent: int) -> str:
        """Render an accordion node — one descriptor per row plus a flat
        child list.

        The descriptors are plain data and go through ``json.dumps``, EXCEPT
        each row's ``title``, which may be a dynamic value (an f-string, a
        state or route reference) and has to be emitted as an expression.
        A widget title is not here at all: it rides in ``children``, and the
        descriptor only records that it does.
        """
        pad = " " * indent
        props = widget.props
        rows = []
        for item in props.get("items", []):
            parts = []
            if "title" in item:
                parts.append(f"title: {self._value_js(item['title'])}")
            for flag in ("titleWidget", "open", "disabled"):
                if item.get(flag):
                    parts.append(f"{flag}: true")
            for text in ("icon", "key"):
                if item.get(text) is not None:
                    parts.append(f"{text}: {json.dumps(item[text])}")
            rows.append("{ " + ", ".join(parts) + " }")
        entries = [
            "items: [" + ", ".join(rows) + "]",
            f"variant: {json.dumps(props.get('variant', 'default'))}",
        ]
        if "indicator" in props:
            entries.append(f"indicator: {json.dumps(props['indicator'])}")
        if props.get("separators") is False:
            entries.append("separators: false")
        if props.get("exclusive"):
            entries.append("exclusive: true")
        if "value" in props:
            entries.append(f"value: {self._gen_expr(props['value'])}")
        if "onChange" in props:
            entries.append(f"onChange: {self._handler_js(props['onChange'])}")
        if "key" in props:
            entries.append(f"key: {json.dumps(props['key'])}")
        # `_with_extras` splices in `style={...}` and the universal
        # interaction handlers. Without it they parse cleanly and then
        # vanish — no error, no effect — which is the failure mode the
        # helper's own docstring warns about, and the reason `Accordion`
        # was added to `_STYLEABLE_WIDGETS` in the first place.
        props_js = self._with_extras("{ " + ", ".join(entries) + " }", widget)
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "accordion",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_tabs(self, widget: WidgetIR, indent: int) -> str:
        """Render a tabs node — a bar of labels + one panel per child. ``labels``
        is an array of (possibly dynamic) strings; ``value``/``onChange`` are the
        optional controlled binding + handler; the panels are the children."""
        pad = " " * indent
        props = widget.props
        labels = ", ".join(self._value_js(la) for la in props.get("labels", []))
        entries = [
            f"labels: [{labels}]",
            f"placement: {json.dumps(props.get('placement', 'top'))}",
        ]
        # Only what differs from the design's default is emitted, so an
        # ordinary Tabs() stays a two-key object in the bundle.
        if props.get("variant", "primary") != "primary":
            entries.append(f"variant: {json.dumps(props['variant'])}")
        if props.get("size", "md") != "md":
            entries.append(f"size: {json.dumps(props['size'])}")
        if props.get("rounded"):
            entries.append("rounded: true")
        if props.get("heads"):
            entries.append(f"heads: {json.dumps(props['heads'])}")
        if "value" in props:
            entries.append(f"value: {self._gen_expr(props['value'])}")
        if "on_change" in props:
            entries.append(f"onChange: {self._handler_js(props['on_change'])}")
        if "key" in props:
            entries.append(f"key: {json.dumps(props['key'])}")
        props_js = "{ " + ", ".join(entries) + " }"
        children_js = self._gen_children(widget.children, indent + 2)
        return (
            f'Workpeg.h(\n{pad}  "tabs",\n{pad}  {props_js},\n'
            f"{pad}  {children_js}\n{pad})"
        )

    def _gen_children(self, children: list[WidgetIR], indent: int) -> str:
        if not children:
            return "[]"
        pad = " " * indent
        items = [f"{pad}  {self._gen_widget(c, indent + 2)}" for c in children]
        return "[\n" + ",\n".join(items) + "\n" + pad + "]"

    def _gen_conditional(self, widget: WidgetIR, indent: int) -> str:
        """Render a conditional widget as a ternary chain.

        ``(t1) ? w1 : (t2) ? w2 : default`` — an unconditional branch (test
        None) is the default; without one the final else is ``null``, which
        the runtime renders as an empty node.
        """
        pad = " " * indent
        result = "null"
        for branch in reversed(widget.props["branches"]):
            child = self._gen_widget(branch["widget"], indent)
            if branch["test"] is None:
                result = child
            else:
                cond = self._gen_test(branch["test"])
                result = f"({cond})\n{pad}? {child}\n{pad}: {result}"
        return result

    def _text_to_js(self, value: str) -> str:
        """Compile a text string to a JS string/template.

        A text value may use ``${field}`` / ``${location.attr}`` interpolation
        (a state field, or a window.location attribute). Any *other* ``${...}``
        is NOT a valid interpolation and is emitted as **literal text**, never a
        live template expression — so a string can never smuggle arbitrary JS
        (``${constructor.constructor('…')()}``) past the restricted compiler.
        """
        if "${" not in value:
            return json.dumps(value)
        out = ["`"]
        i, n = 0, len(value)
        while i < n:
            ch = value[i]
            if ch == "$" and i + 1 < n and value[i + 1] == "{":
                close = value.find("}", i + 2)
                inner = value[i + 2:close] if close != -1 else None
                # The same names the parser holds a field or a location read
                # to, because this is a second way to spell one: anything else
                # falls through to literal text.
                if (inner is not None and inner.isidentifier()
                        and inner not in _OBJECT_PROTOTYPE_NAMES
                        and not _is_dunder(inner)
                        and not self._state_is_a_prop):
                    out.append("${this.state." + inner + "}")  # a state field
                    i = close + 1
                elif (inner is not None
                        and re.fullmatch(r"location\.\w+", inner)
                        and inner[len("location."):] in _LOCATION_PROPS):
                    out.append("${window." + inner + "}")       # window.location
                    i = close + 1
                else:                                            # not an interp.
                    out.append("\\${")                           # literal "${"
                    i += 2
            else:
                out.append(_escape_template_text(ch))
                i += 1
        out.append("`")
        return "".join(out)
